"use client"

import { Menu as MenuPrimitive } from "@base-ui/react/menu"
import { CheckIcon, ChevronRightIcon } from "lucide-react"
import type * as React from "react"
import { createContext, useContext } from "react"

import { cn } from "@/lib/utils"

import { GlassCard } from "./liquid-glass/glass-card"
import {
  type GlassPopupFrom,
  type GlassPopupOpening,
  GlassPopupAnchor,
  GlassPopupContext,
  GlassPopupSurface,
  OVER_EDGE,
  spellLabel,
  useGlassPopup,
} from "./liquid-glass/glass-popup"

export type { GlassPopupFrom, GlassPopupOpening }
export type GlassDropdownMenuOpening = GlassPopupOpening

export const GlassDropdownMenuCreateHandle: typeof MenuPrimitive.createHandle =
  MenuPrimitive.createHandle

const GlassDropdownMenuOpeningContext =
  createContext<GlassPopupOpening>("stretch")

const ROW_CLASS =
  "relative flex h-10 cursor-pointer items-center gap-2.5 rounded-2xl px-3.5 font-medium whitespace-nowrap outline-none select-none transition-colors duration-100 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-40 data-[highlighted]:bg-current/10 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0 [&>svg:not([class*='opacity-'])]:opacity-80"

const SURFACE_CLASS =
  "min-w-48 rounded-3xl p-1.5 text-[15px] text-neutral-900 outline-none data-[glass-tone=dark]:text-white data-[glass-tone=light]:text-neutral-900"

export type GlassDropdownMenuProps = MenuPrimitive.Root.Props & {
  /** Opening physics preset: "stretch" (default), "morph", or "grow". */
  opening?: GlassPopupOpening
  /** With opening="morph", direction the surface arrives from. */
  from?: GlassPopupFrom
  /** Keep popup width aligned to the trigger width. @default false */
  matchWidth?: boolean
}

/**
 * Liquid Glass Dropdown Menu built natively on `@base-ui/react/menu` and the
 * shared WebGL2 SDF liquid-glass engine (`liquid-glass/glass-popup`).
 */
export function GlassDropdownMenu({
  opening = "stretch",
  from = "top",
  matchWidth = false,
  ...props
}: GlassDropdownMenuProps): React.ReactElement {
  const popup = useGlassPopup({ matchWidth, opening, from })

  return (
    <GlassDropdownMenuOpeningContext.Provider value={opening}>
      <GlassPopupContext.Provider value={popup}>
        <MenuPrimitive.Root data-slot="glass-dropdown-menu" {...props} />
      </GlassPopupContext.Provider>
    </GlassDropdownMenuOpeningContext.Provider>
  )
}

export const GlassDropdownMenuPortal: typeof MenuPrimitive.Portal =
  MenuPrimitive.Portal

export type GlassDropdownMenuTriggerProps = MenuPrimitive.Trigger.Props & {
  size?: "sm" | "default" | "lg"
  /** Use "morph" if the parent GlassDropdownMenu uses opening="morph" for letter-by-letter label reveal. */
  opening?: GlassPopupOpening
}

export function GlassDropdownMenuTrigger({
  className,
  size = "default",
  opening,
  children,
  ...props
}: GlassDropdownMenuTriggerProps): React.ReactElement {
  const popup = useContext(GlassPopupContext)
  const inheritedOpening = useContext(GlassDropdownMenuOpeningContext)
  const resolvedOpening = opening ?? inheritedOpening

  return (
    <MenuPrimitive.Trigger
      data-slot="glass-dropdown-menu-trigger"
      data-glass-host=""
      data-size={size}
      className={cn(
        "relative inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 rounded-full border border-black/10 bg-white/60 px-5 font-medium whitespace-nowrap text-neutral-900 outline-none select-none",
        "focus-visible:ring-2 focus-visible:ring-[#3291FF] focus-visible:ring-offset-2",
        "disabled:cursor-not-allowed disabled:opacity-40",
        "data-[size=default]:h-11 data-[size=default]:text-[15px] data-[size=lg]:h-12 data-[size=lg]:text-[15px] data-[size=sm]:h-9 data-[size=sm]:px-4 data-[size=sm]:text-sm",
        "dark:border-white/15 dark:bg-white/10 dark:text-white",
        "data-[glass-tone=dark]:text-white data-[glass-tone=light]:text-neutral-900",
        "[&_svg]:size-4 [&_svg]:shrink-0",
        className
      )}
      {...props}
    >
      {popup && <GlassPopupAnchor popup={popup} />}
      <span className="inline-flex items-center gap-[inherit]">
        {resolvedOpening === "morph" ? spellLabel(children) : children}
      </span>
    </MenuPrimitive.Trigger>
  )
}

export type GlassDropdownMenuContentProps = MenuPrimitive.Popup.Props & {
  align?: MenuPrimitive.Positioner.Props["align"]
  sideOffset?: MenuPrimitive.Positioner.Props["sideOffset"]
  alignOffset?: MenuPrimitive.Positioner.Props["alignOffset"]
  side?: MenuPrimitive.Positioner.Props["side"]
  anchor?: MenuPrimitive.Positioner.Props["anchor"]
  portalProps?: MenuPrimitive.Portal.Props
  /** Override the opening mode inherited from GlassDropdownMenu. */
  opening?: GlassPopupOpening
}

export function GlassDropdownMenuContent({
  children,
  className,
  sideOffset,
  align = "center",
  alignOffset = 0,
  side = "bottom",
  anchor,
  portalProps,
  opening,
  ...props
}: GlassDropdownMenuContentProps): React.ReactElement {
  const popup = useContext(GlassPopupContext)
  const inheritedOpening = useContext(GlassDropdownMenuOpeningContext)
  const resolvedOpening = opening ?? inheritedOpening
  const resolvedSideOffset =
    sideOffset ??
    (resolvedOpening === "morph" ? 0 : resolvedOpening === "grow" ? 8 : 12)

  return (
    <GlassDropdownMenuPortal {...portalProps}>
      <MenuPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        anchor={anchor}
        className="isolate z-50 outline-none"
        data-slot="glass-dropdown-menu-positioner"
        side={side}
        sideOffset={resolvedSideOffset}
      >
        <MenuPrimitive.Popup
          data-slot="glass-dropdown-menu-content"
          data-glass-popup=""
          data-glass-skip=""
          className={cn(
            "group/glass relative",
            SURFACE_CLASS,
            resolvedOpening === "morph" && OVER_EDGE,
            className
          )}
          {...props}
        >
          {popup && <GlassPopupSurface popup={popup} />}
          {/* Submenus use their own GlassCard surface, independent of the root popup context. */}
          <GlassPopupContext.Provider value={null}>
            <div data-glass-list="" className="flex flex-col">
              {children}
            </div>
          </GlassPopupContext.Provider>
        </MenuPrimitive.Popup>
      </MenuPrimitive.Positioner>
    </GlassDropdownMenuPortal>
  )
}

export function GlassDropdownMenuGroup({
  className,
  ...props
}: MenuPrimitive.Group.Props): React.ReactElement {
  return (
    <MenuPrimitive.Group
      data-slot="glass-dropdown-menu-group"
      className={cn("flex flex-col", className)}
      {...props}
    />
  )
}

export function GlassDropdownMenuLabel({
  className,
  inset,
  ...props
}: MenuPrimitive.GroupLabel.Props & {
  inset?: boolean
}): React.ReactElement {
  return (
    <MenuPrimitive.GroupLabel
      data-inset={inset}
      data-slot="glass-dropdown-menu-label"
      className={cn(
        "px-3.5 pt-2 pb-1 text-xs font-medium opacity-55 select-none data-inset:ps-9",
        className
      )}
      {...props}
    />
  )
}

export function GlassDropdownMenuSeparator({
  className,
  ...props
}: MenuPrimitive.Separator.Props): React.ReactElement {
  return (
    <MenuPrimitive.Separator
      data-slot="glass-dropdown-menu-separator"
      className={cn("mx-3.5 my-1 h-px shrink-0 bg-current/15", className)}
      {...props}
    />
  )
}

export function GlassDropdownMenuShortcut({
  className,
  ...props
}: React.ComponentProps<"kbd">): React.ReactElement {
  return (
    <kbd
      data-slot="glass-dropdown-menu-shortcut"
      className={cn(
        "ms-auto pl-6 font-sans text-[13px] font-normal tracking-wide opacity-50",
        className
      )}
      {...props}
    />
  )
}

function resolveGlassItemStyle<TState>(
  index: number,
  style:
    | React.CSSProperties
    | ((state: TState) => React.CSSProperties | undefined)
    | undefined
): React.CSSProperties | ((state: TState) => React.CSSProperties) {
  const baseVars: React.CSSProperties & { "--glass-i"?: number } = {
    "--glass-i": index,
  }

  return typeof style === "function"
    ? (state: TState) => ({ ...baseVars, ...style(state) })
    : { ...baseVars, ...style }
}

export type GlassDropdownMenuItemProps = MenuPrimitive.Item.Props & {
  inset?: boolean
  variant?: "default" | "destructive"
  /** Queue index for staggered item reveal inside GlassDropdownMenuContent. */
  index?: number
}

export function GlassDropdownMenuItem({
  className,
  inset,
  variant = "default",
  index = 0,
  style,
  ...props
}: GlassDropdownMenuItemProps): React.ReactElement {
  return (
    <MenuPrimitive.Item
      data-inset={inset}
      data-variant={variant}
      data-slot="glass-dropdown-menu-item"
      data-glass-item=""
      style={resolveGlassItemStyle(index, style)}
      className={cn(
        ROW_CLASS,
        "data-inset:ps-9",
        "data-[variant=destructive]:text-red-600 group-data-[glass-tone=dark]/glass:data-[variant=destructive]:text-red-400",
        "data-[variant=destructive]:data-[highlighted]:bg-red-500/12",
        className
      )}
      {...props}
    />
  )
}

export type GlassDropdownMenuLinkItemProps = MenuPrimitive.LinkItem.Props & {
  inset?: boolean
  variant?: "default" | "destructive"
  /** Queue index for staggered item reveal inside GlassDropdownMenuContent. */
  index?: number
}

export function GlassDropdownMenuLinkItem({
  className,
  inset,
  variant = "default",
  closeOnClick = true,
  index = 0,
  style,
  ...props
}: GlassDropdownMenuLinkItemProps): React.ReactElement {
  return (
    <MenuPrimitive.LinkItem
      closeOnClick={closeOnClick}
      data-inset={inset}
      data-variant={variant}
      data-slot="glass-dropdown-menu-link-item"
      data-glass-item=""
      style={resolveGlassItemStyle(index, style)}
      className={cn(
        ROW_CLASS,
        "data-inset:ps-9",
        "data-[variant=destructive]:text-red-600 group-data-[glass-tone=dark]/glass:data-[variant=destructive]:text-red-400",
        "data-[variant=destructive]:data-[highlighted]:bg-red-500/12",
        className
      )}
      {...props}
    />
  )
}

export type GlassDropdownMenuCheckboxItemProps =
  MenuPrimitive.CheckboxItem.Props & {
    variant?: "default" | "switch"
    /** Queue index for staggered item reveal inside GlassDropdownMenuContent. */
    index?: number
  }

export function GlassDropdownMenuCheckboxItem({
  className,
  children,
  checked,
  variant = "default",
  index = 0,
  style,
  ...props
}: GlassDropdownMenuCheckboxItemProps): React.ReactElement {
  return (
    <MenuPrimitive.CheckboxItem
      checked={checked}
      data-slot="glass-dropdown-menu-checkbox-item"
      data-glass-item=""
      style={resolveGlassItemStyle(index, style)}
      className={cn(
        ROW_CLASS,
        variant === "switch" && "justify-between gap-4 pe-2.5",
        className
      )}
      {...props}
    >
      {variant === "switch" ? (
        <>
          <span className="truncate">{children}</span>
          <MenuPrimitive.CheckboxItemIndicator
            className="inline-flex h-5 w-8.5 shrink-0 items-center rounded-full bg-current/20 p-0.5 transition-colors duration-200 outline-none data-checked:bg-current/85 data-disabled:opacity-60"
            keepMounted
          >
            <span className="pointer-events-none block size-4 rounded-full bg-white shadow-sm transition-transform duration-150 dark:bg-neutral-950 in-[[data-slot=glass-dropdown-menu-checkbox-item][data-checked]]:translate-x-3.5" />
          </MenuPrimitive.CheckboxItemIndicator>
        </>
      ) : (
        <>
          <span className="truncate">{children}</span>
          <MenuPrimitive.CheckboxItemIndicator className="ms-auto pl-4">
            <CheckIcon aria-hidden="true" className="size-3.5" />
          </MenuPrimitive.CheckboxItemIndicator>
        </>
      )}
    </MenuPrimitive.CheckboxItem>
  )
}

export function GlassDropdownMenuRadioGroup({
  className,
  ...props
}: MenuPrimitive.RadioGroup.Props): React.ReactElement {
  return (
    <MenuPrimitive.RadioGroup
      data-slot="glass-dropdown-menu-radio-group"
      className={cn("flex flex-col", className)}
      {...props}
    />
  )
}

export type GlassDropdownMenuRadioItemProps = MenuPrimitive.RadioItem.Props & {
  /** Queue index for staggered item reveal inside GlassDropdownMenuContent. */
  index?: number
}

export function GlassDropdownMenuRadioItem({
  className,
  children,
  index = 0,
  style,
  ...props
}: GlassDropdownMenuRadioItemProps): React.ReactElement {
  return (
    <MenuPrimitive.RadioItem
      data-slot="glass-dropdown-menu-radio-item"
      data-glass-item=""
      style={resolveGlassItemStyle(index, style)}
      className={cn(ROW_CLASS, className)}
      {...props}
    >
      <span className="truncate">{children}</span>
      <MenuPrimitive.RadioItemIndicator className="ms-auto pl-4">
        <span aria-hidden className="block size-2 rounded-full bg-current" />
      </MenuPrimitive.RadioItemIndicator>
    </MenuPrimitive.RadioItem>
  )
}

export function GlassDropdownMenuSub(
  props: MenuPrimitive.SubmenuRoot.Props
): React.ReactElement {
  return (
    <MenuPrimitive.SubmenuRoot
      data-slot="glass-dropdown-menu-sub"
      {...props}
    />
  )
}

export type GlassDropdownMenuSubTriggerProps =
  MenuPrimitive.SubmenuTrigger.Props & {
    inset?: boolean
    /** Queue index for staggered item reveal inside GlassDropdownMenuContent. */
    index?: number
  }

export function GlassDropdownMenuSubTrigger({
  className,
  inset,
  index = 0,
  style,
  children,
  ...props
}: GlassDropdownMenuSubTriggerProps): React.ReactElement {
  return (
    <MenuPrimitive.SubmenuTrigger
      data-inset={inset}
      data-slot="glass-dropdown-menu-sub-trigger"
      data-glass-item=""
      style={resolveGlassItemStyle(index, style)}
      className={cn(
        ROW_CLASS,
        "data-inset:ps-9 data-popup-open:bg-current/10",
        className
      )}
      {...props}
    >
      {children}
      <ChevronRightIcon
        aria-hidden="true"
        className="ms-auto size-4 opacity-50 rtl:-scale-x-100"
      />
    </MenuPrimitive.SubmenuTrigger>
  )
}

export type GlassDropdownMenuSubContentProps = MenuPrimitive.Popup.Props & {
  align?: MenuPrimitive.Positioner.Props["align"]
  sideOffset?: MenuPrimitive.Positioner.Props["sideOffset"]
  alignOffset?: MenuPrimitive.Positioner.Props["alignOffset"]
  side?: MenuPrimitive.Positioner.Props["side"]
  portalProps?: MenuPrimitive.Portal.Props
}

export function GlassDropdownMenuSubContent({
  className,
  children,
  sideOffset = 14,
  alignOffset = -6,
  align = "start",
  side = "inline-end",
  portalProps,
  ...props
}: GlassDropdownMenuSubContentProps): React.ReactElement {
  return (
    <MenuPrimitive.Portal {...portalProps}>
      <MenuPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        className="isolate z-50 outline-none"
        data-slot="glass-dropdown-menu-sub-positioner"
        side={side}
        sideOffset={sideOffset}
      >
        <MenuPrimitive.Popup
          data-slot="glass-dropdown-menu-sub-content"
          data-glass-skip=""
          render={
            <GlassCard
              className={cn(
                "group/glass",
                SURFACE_CLASS,
                "overflow-visible! transition-[opacity,scale] duration-150 ease-out data-ending-style:scale-[0.97] data-ending-style:opacity-0 data-starting-style:scale-[0.97] data-starting-style:opacity-0 motion-reduce:scale-100!",
                className
              )}
            />
          }
          {...props}
        >
          <div className="flex flex-col">{children}</div>
        </MenuPrimitive.Popup>
      </MenuPrimitive.Positioner>
    </MenuPrimitive.Portal>
  )
}

export default GlassDropdownMenu

"use client"

// GlassPopup â the gooey popup, as a building block. A surface (a select's list, a menu, a
// popover) and the control that opens it are one body of liquid glass: the surface swells out of
// the whole anchor, a neck gathers between them, thins and snaps, both halves take the jolt, and
// the options come in one after another. Closing is the same motion played backwards.
//
//   const popup = useGlassPopup()
//   <button data-glass-host className="rounded-full â¦">     // the anchor: any positioned control
//     <GlassPopupAnchor popup={popup} />                     //   first child
//     Open
//   </button>
//   <Content data-glass-popup data-glass-skip className="rounded-3xl â¦">   // the popup's content
//     <GlassPopupSurface popup={popup} />                                   //   first child
//     <div role="menu">
//       <div role="menuitem" style={{ '--glass-i': 0 }}>â¦</div>          // --glass-i: its place in the queue
//     </div>
//   </Content>
//
// Contract (what UI SDK's popups do; any headless library that does the same works): the content
// carries `data-open` while open and `data-ending-style` while it closes, and stays mounted
// until every animation inside it has finished. An empty element (`data-glass-hold`) runs a
// long transition while closing and is finished the moment the glass is back inside the anchor:
// the WebGL exit decides when the popup leaves. Items are `role="option"`, `role="menuitem"` or
// `data-glass-item`, inside `role="listbox"`, `role="menu"` or `data-glass-list`. A press on one
// lights the surface where it lands; `data-glass-pick` gives that light to any other control inside.
// One shape, two canvases: the part inside the anchor's box is drawn beneath its label, the rest
// in the popup's layer (the top layer included). Both draw the same field, so the seam cannot show.
// `useGlassPopup({ opening: 'morph' })` is the other way out: the control itself becomes the
// surface. The same two glasses as above (Button's on the control, Card's on the surface) and
// the same light, with the surface coming out over the control: it grows from the control's box
// to its own (round all the way, a little past it, then settled), the control's label softens
// and goes, its glass gives way to the card and the list comes into focus inside. The surface
// lies over the control then: give the content `sideOffset={-<the control's height>}`. One
// canvas, the surface's, draws both glasses while it is out. It closes by a calmer motion of its
// own: the content goes first, the surface slides back into the control and slows as it lands.
// `useGlassPopup({ opening: 'grow' })` is the third way: the control's glass is the surface.
// One shape on one spring: the control's outline grows into the surface's, wherever the surface
// lies (below, above or beside the control: no negative `sideOffset`), and shrinks back along the
// same path. The side the surface lies on runs ahead, the other follows. The control's label
// goes as the glass leaves it, and the surface's content stays in place while the glass opens
// over it. Reversed half way, it carries on from where it is. The press that opens it lights the
// glass where it landed, and that light fades in its place: it does not widen with the glass as
// the others' does, and nothing spills past its edge.
// GlassMenu is built on it.
// The light of a press follows the kit's rule (above GLOW in engine.ts): the control is a button
// and takes the flash of a press, which here goes on to open the surface; the surface is a
// surface, and a press in it is lit by the engine's own light (LIGHT), where it lands. The list
// of a stretching or a morphing surface keeps its choice light on top of that.
// Shut, the control is a button: held, it stays shut, swells and is pulled after the pointer
// (PULL in engine.ts), and the surface opens when the press is let go on it, from wherever the
// pull has the glass. Let go away from the control, nothing opens.
// A label that comes back letter by letter: the label of a morphing control goes in
// <GlassPopupText> (GlassPopover and GlassDropdownMenu do it for their own triggers). The moment
// its surface is back in, the label returns letter by letter,
// out of a blur and the dark.
// Without WebGL2 the surface is a plain frosted panel and the anchor keeps its CSS look.
// COPY VERBATIM. MIT â https://github.com/bilalgursen/liquid-glass

import {
  Children,
  createContext,
  useEffect,
  useMemo,
  useRef,
  type CSSProperties,
  type ReactNode,
} from "react"

import { drawAround, drawDom } from "./dom-snapshot"
import {
  GLOW,
  GLOW_SMALL,
  GOOEY,
  HANDED_ON,
  MENU,
  MORPH,
  MORPH_GLOW,
  MORPH_GLOW_SMALL,
  SPRINGS,
  clamp,
  getGlassEngine,
  lerp,
  rgbCss,
  smooth,
  stepSpring,
  surfaceColorOf,
  type GlassEngine,
  type GlassLens,
  type GlassView,
  type Rgb,
  type Spring,
} from "./engine"
import { GlassStyles } from "./glass-layer"

const DESIGN_HEIGHT = 120
/** The control is GlassButton's glass: its tint, no frost, its light and shadow. */
const TINT = 0.6
/** The surface is GlassCard's glass from the moment it leaves the control: frosted, with its tighter bend. */
const CARD = { tint: 0.7, blur: 5, bendCurve: 9.75, bendDepth: 1.35 }
/** Under a control painted in its own colour, the surface's tint covers this much. */
const FILLED = 0.92
/** The surface has no light of its own: this thin white line draws its edge, a soft CSS shadow lifts it. */
const LINE = { alpha: 0.6, darkAlpha: 0.25, width: 1.3 }
/** Room around the trigger's own canvas, and around the popup's. */
const TRIGGER_PAD = 16
/** How far (px) the control's canvas reaches past the seam, under the popup's, so no line shows where they meet. */
const SEAM_OVERLAP = 1
const PAD = 28
const PAD_BOTTOM = 56
const TUNE = GOOEY
const ITEMS = ":is([role=option],[role=menuitem],[data-glass-item])"
/** What lights the surface where it is pressed: the items, and anything marked `data-glass-pick` (a popover's Close). */
const PICKS =
  ":is([role=option],[role=menuitem],[data-glass-item],[data-glass-pick])"
const LIST = ":is([role=listbox],[role=menu],[data-glass-list])"
/** Closing, a stretching surface's list is gone this long (seconds) after the close begins, ahead of the glass. */
const LIST_OUT = 0.07
/** What a morphing surface writes on its content for the list: where it is, how large, its cut and its focus. */
const RIDE = [
  "--glass-ride-x",
  "--glass-ride-y",
  "--glass-zoom",
  "--glass-clip",
  "--glass-soft",
]
/** The bridge forms fast; once the thread has broken, what is left of the tension lets go at once. */
const ATTACH = { omega: 28, zeta: 1 }
const LET_GO = { omega: 16, zeta: 1 }
/** How far through the opening the near edge has crossed the gap, and the list shows. */
const NEAR_EDGE = 0.3
/** Closed, the control answers the pointer as GlassButton does (GlassLayer's own values). */
const PRESS_SCALE = 1.08
const HOVER_SCALE = 1.04
const HOVER_GROW = 0.08
const MAX_GROW_PX = 6
/** Once the popup is back inside it, the control swells as if hovered for this long (seconds), then lets go. */
const SETTLE = 0.16
/** A morphing control lights up as it takes its surface back: this much of a press, at its middle. */
const SETTLE_GLOW = 0.7
/** What a morphing popup's light does to the content on it: how much it brightens it (Ã the light there), and the soft white bloom it leaves around it (px, alpha). */
const CONTENT_GLOW = { lift: 0.55, bloom: 7, alpha: 0.65 }
/** Each letter of it: how long it takes (seconds), how long after the one before it starts, how soft it starts (CSS px). */
const LETTER = { duration: 0.4, gap: 0.01, blur: 10 }
/** A morphing surface's content follows each side of the glass, at most this much (Ã) off its even size: past it, text would look stretched. */
const MAX_STRETCH = 1.06
/**
 * The content's blur ends at this many device px instead of thinning to nothing: under about one and
 * a half, WebKit (iOS Safari) draws the clipped list with a magenta line down its side.
 */
const SOFT_MIN = 2
/** The content's blur (`soft`, CSS px) as a filter, or none once it is under SOFT_MIN. */
const softBlur = (soft: number, digits: number) =>
  soft * (typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1) >=
  SOFT_MIN
    ? `blur(${soft.toFixed(digits)}px)`
    : ""

/**
 * How much (0â1) a box `ox, oy` off the glass's middle, `w Ã h` half its size, must shrink to lie
 * inside the rounded glass `g` (half sizes `hx, hy`, corner radius `r`).
 */
function fitIn(
  g: { hx: number; hy: number; r: number },
  ox: number,
  oy: number,
  w: number,
  h: number
) {
  const r = Math.min(g.r, g.hx, g.hy)
  const inside = (k: number) => {
    const dx = Math.abs(ox * k) + w * k
    const dy = Math.abs(oy * k) + h * k
    if (dx > g.hx + 0.5 || dy > g.hy + 0.5) return false
    const qx = dx - (g.hx - r)
    const qy = dy - (g.hy - r)
    return qx <= 0 || qy <= 0 || qx * qx + qy * qy <= (r + 0.5) * (r + 0.5)
  }
  if (inside(1)) return 1
  let lo = 0.2
  let hi = 1
  for (let i = 0; i < 12; i++) {
    const mid = (lo + hi) / 2
    if (inside(mid)) lo = mid
    else hi = mid
  }
  return lo
}

