export const lerp = (a: number, b: number, t: number) => a + (b - a) * t
export const clamp = (v: number, a = 0, b = 1) => Math.max(a, Math.min(b, v))
export const smooth = (a: number, b: number, v: number) => {
  const t = clamp((v - a) / (b - a))
  return t * t * (3 - 2 * t)
}
export const mixRgb = (a: Rgb, b: Rgb, t: number): Rgb => [
  lerp(a[0], b[0], t),
  lerp(a[1], b[1], t),
  lerp(a[2], b[2], t),
]
export const rgbCss = (c: Rgb) =>
  `rgb(${Math.round(c[0] * 255)} ${Math.round(c[1] * 255)} ${Math.round(c[2] * 255)})`

const isVisibleColor = (c: string) =>
  !!c &&
  c !== "transparent" &&
  !/rgba\(.*,\s*0\)$/.test(c) &&
  !/\/\s*0\)$/.test(c)

/** The colour an element sits on: the first ancestor with a painted background. */
export function surfaceColorOf(el: Element | null): string {
  for (let a = el; a; a = a.parentElement) {
    const c = getComputedStyle(a).backgroundColor
    if (isVisibleColor(c)) return c
  }
  return getComputedStyle(document.documentElement).colorScheme.includes("dark")
    ? "black"
    : "white"
}

