    const held = s.press || s.key
    const target = LIGHT.on && held ? LIGHT.press : 0
    if (still) {
      const changed = s.glow.x !== target
      s.glow.x = target
      s.glow.v = 0
      return changed
    }
    return stepSpring(
      s.glow,
      target,
      held
        ? {
            omega: (2 * Math.PI) / Math.max(LIGHT.rise, 0.01),
            zeta: clamp(1 - LIGHT.riseBounce, 0.05, 1),
          }
        : { omega: (2 * Math.PI) / Math.max(LIGHT.fade, 0.01), zeta: 1 },
      dt
    )
  }

  // The flash of a press on a button (GLOW): the rule above GLOW, applied. A view that says
  // `button: true` is lit where a press lands on it (or at its centre, by Space / Enter): the
  // light comes up, holds for as long as the press does (`hold` at least) and fades as it
  // spreads. Each button keeps its own: how bright, how far it has spread, where it landed (from
  // the host's centre, px), how long it still holds, how many presses' worth is asked for, how
  // small the glass is (which set of values it takes), its height, and what holds it.
  // A surface keeps one too, for a choice pressed in it (`choice`): the same light with GLOW's
  // `select` values, measured in the choice's own height.
  type Flash = {
    glow: Spring
    spread: Spring
    x: number
    y: number
    hold: number
    level: number
    small: number
    height: number
    by: number
    key: boolean
    choice: boolean
  }
  /** What counts as a choice inside a surface. */
  const CHOICES =
    ":is([role=option],[role=menuitem],[data-glass-item],[data-glass-pick])"
  const flashes = new Map<GlassView, Flash>()
  const flashTune = (small: number): typeof GLOW => {
    if (small <= 0) return GLOW
    if (small >= 1) return GLOW_SMALL
    const mixed = { ...GLOW }
    for (const name of Object.keys(mixed) as (keyof typeof GLOW)[])
      mixed[name] = lerp(GLOW[name], GLOW_SMALL[name], small)
    return mixed
  }
  /**
   * Light on this glass at this point (viewport px), or at its centre. Presses that land before
   * the last has faded add up. `choice`: the element chosen inside a surface, whose light it is.
   */
  const flash = (
    v: GlassView,
    x?: number,
    y?: number,
    choice?: HTMLElement
  ) => {
    const host = hostOf(v)
    if (!host) return null
    let f = flashes.get(v)
    if (!f)
      flashes.set(
        v,
        (f = {
          glow: { x: 0, v: 0 },
          spread: { x: 0, v: 0 },
          x: 0,
          y: 0,
          hold: 0,
          level: 0,
          small: 0,
          height: 0,
          by: -1,
          key: false,
          choice: false,
        })
      )
    const r = host.getBoundingClientRect()
    // A light that is still bright keeps spreading from where it is: only a fresh one starts small.
    if (f.glow.x < 0.08) f.spread.x = f.spread.v = 0
    f.x =
      x === undefined
        ? 0
        : clamp(x - (r.left + r.width / 2), -r.width / 2, r.width / 2)
    f.y =
      y === undefined
        ? 0
        : clamp(y - (r.top + r.height / 2), -r.height / 2, r.height / 2)
    f.choice = !!choice
    f.height = (choice ?? host).offsetHeight
    // (A surface takes the wide set of values, whatever its own shape.)
    f.small = choice
      ? 0
      : 1 - smooth(2, 2.4, host.offsetWidth / Math.max(f.height, 1))
    const tune = flashTune(f.small)
    f.level = Math.min(
      Math.max(f.glow.x, 0) + (choice ? tune.select : 1),
      tune.stack
    )
    f.hold = tune.hold
    wake()
    return f
  }
  /** Advances a button's flash; true while it still changes. */
  const stepFlash = (v: GlassView, dt: number, still: boolean) => {
    const f = flashes.get(v)
    if (!f) return false
    if (still) {
      const changed = f.glow.x !== 0
      f.glow.x = f.glow.v = f.spread.x = f.spread.v = f.hold = 0
      return changed
    }
    const lit = f.by !== -1 || f.key || f.hold > 0
    const holding = f.hold > 0
    f.hold = Math.max(0, f.hold - dt)
    const tune = flashTune(f.small)
    const a = stepSpring(
      f.glow,
      lit ? f.level : 0,
      { omega: lit ? tune.riseSpeed : tune.fadeSpeed, zeta: 1 },
      dt
    )
    const b = stepSpring(
      f.spread,
      lit || f.glow.x > 0.004 ? 1 : 0,
      { omega: tune.spreadSpeed, zeta: 1 },
      dt
    )
    // A press held still changes nothing: the loop rests until the hold runs out or the press ends.
    return holding || a || (b && f.glow.x > 0.004)
  }
  /** The flash as a lens's `glow`, for a lens that brings none of its own. (The canvas is scaled with the host: the light is measured on the page, so it is divided by that scale.) */
  const flashOf = (v: GlassView): GlassLens["glow"] => {
    const f = flashes.get(v)
    if (!f || f.glow.x <= 0.004) return undefined
    const tune = flashTune(f.small)
    const k = Math.max(0.5, v.grow ?? 1)
    const far = clamp(f.spread.x)
    const reach = f.choice
      ? tune.selectReach + tune.selectSpread * far
      : tune.reach + tune.spread * far
    return {
      x: f.x / k,
      y: f.y / k,
      r: f.height * reach,
      amount: Math.max(0, f.glow.x) * tune.amount,
      blob: 1,
    }
  }

  // Pull (PULL): glass a held pointer drags after itself, where the view asks for it (buttons).
  // One pointer holds one glass, the innermost under the press. The engine moves its host (CSS `translate`) and stretches it (CSS
  // `scale`, times the view's own `grow`), and lets go when the pointer does.
  type Pulled = {
    /** How far the glass has come after the pointer, each way (px). */
    x: Spring
    y: Spring
    /** The pointer that holds it: where it pressed, where it is, and where the glass rested then. */
    by: {
      id: number
      x: number
      y: number
      nowX: number
      nowY: number
      cx: number
      cy: number
      lastX: number
      lastY: number
      size: number
    } | null
    /** How fast the glass's own place on the page moves while held (px/s, smoothed). */
    driftX: number
    driftY: number
    /** The host's own CSS `translate` (a centring class), which the pull adds to. */
    own: string[] | null
    /** What the engine last wrote on the host. */
    moved: string
    scaled: string
  }
  const pulls = new Map<GlassView, Pulled>()
  const pulledOf = (v: GlassView) => {
    let p = pulls.get(v)
    if (!p)
      pulls.set(
        v,
        (p = {
          x: { x: 0, v: 0 },
          y: { x: 0, v: 0 },
          by: null,
          driftX: 0,
          driftY: 0,
          own: null,
          moved: "",
          scaled: "",
        })
      )
    return p
  }
  /** The centre of the glass on screen where it rests, without the pull. */
  const restOf = (host: HTMLElement, p: Pulled) => {
    const r = host.getBoundingClientRect()
    return { x: r.left + r.width / 2 - p.x.x, y: r.top + r.height / 2 - p.y.x }
  }
  const letGo = (v: GlassView, p: Pulled) => {
    p.by = null
    v.held = false
  }
  /** Advances a view's pull and writes its host's `translate` and `scale`; true while it still moves. */
  const stepPull = (v: GlassView, dt: number, still: boolean) => {
    const p = pulls.get(v)
    if (!p && v.grow === undefined) return false
    const host = hostOf(v)
    if (!host) return false
    const s = p ?? pulledOf(v)
    if (s.by && (v.pull !== true || !PULL.on)) letGo(v, s)
    let sx = 1
    let sy = 1
    let moving = false
    if (still) {
      s.x.x = s.x.v = s.y.x = s.y.v = s.driftX = s.driftY = 0
    } else if (
      s.by ||
      s.x.x !== 0 ||
      s.y.x !== 0 ||
      s.x.v !== 0 ||
      s.y.v !== 0 ||
      s.driftX !== 0 ||
      s.driftY !== 0
    ) {
      const w = Math.max(host.offsetWidth, 1)
      const h = Math.max(host.offsetHeight, 1)
      const size = Math.max(w, h)
      const small = size <= PULL.smallUntil
      let tx = 0
      let ty = 0
      const by = s.by
      if (by) {
        const at = restOf(host, s)
        // Small glass: how far the pointer has gone since the press. Larger: how far past the edge it is.
        const dx = small
          ? by.nowX - by.x - (at.x - by.cx)
          : by.nowX - clamp(by.nowX, at.x - w / 2, at.x + w / 2)
        const dy = small
          ? by.nowY - by.y - (at.y - by.cy)
          : by.nowY - clamp(by.nowY, at.y - h / 2, at.y + h / 2)
        const limit = small
          ? PULL.smallReach + PULL.smallReachPerPx * size
          : Math.min(PULL.reachMax, PULL.reach + PULL.reachPerPx * size)
        tx = rubberBand(dx, limit, PULL.resistance)
        ty = rubberBand(dy, limit, PULL.resistance)
        if (dt > 0) {
          s.driftX +=
            ((at.x - by.lastX) / dt - s.driftX) * Math.min(1, dt * PULL.driftIn)
          s.driftY +=
            ((at.y - by.lastY) / dt - s.driftY) * Math.min(1, dt * PULL.driftIn)
        }
        by.lastX = at.x
        by.lastY = at.y
      } else {
        s.driftX =
          Math.abs(s.driftX) < 1 ? 0 : s.driftX * Math.exp(-dt * PULL.driftOut)
        s.driftY =
          Math.abs(s.driftY) < 1 ? 0 : s.driftY * Math.exp(-dt * PULL.driftOut)
      }
      const spring = by
        ? {
            omega: (2 * Math.PI) / (PULL.follow + PULL.followPerPx * by.size),
            zeta: 1,
          }
        : { omega: (2 * Math.PI) / PULL.release, zeta: 1 - PULL.releaseBounce }
      const mx = stepSpring(s.x, tx, spring, dt)
      const my = stepSpring(s.y, ty, spring, dt)
      const most = small ? PULL.smallStretchMax : PULL.stretchMax
      const along = (pull: Spring, length: number, drift: number) =>
        Math.min(
          most,
          (PULL.stretch * Math.abs(pull.x)) / length +
            PULL.stretchPerSpeed * Math.abs(pull.v) +
            PULL.stretchPerDrift * Math.abs(drift)
        )
      const kx = along(s.x, w, s.driftX)
      const ky = along(s.y, h, s.driftY)
      sx = (1 + kx) / Math.sqrt(1 + ky)
      sy = (1 + ky) / Math.sqrt(1 + kx)
      moving = !!by || mx || my || s.driftX !== 0 || s.driftY !== 0
    }
    const on = Math.abs(s.x.x) > 0.01 || Math.abs(s.y.x) > 0.01
    const px = `${s.x.x.toFixed(3)}px`
    const py = `${s.y.x.toFixed(3)}px`
    const moved = !on
      ? ""
      : s.own
        ? `calc(${s.own[0]} + ${px}) calc(${s.own[1] ?? "0px"} + ${py})`
        : `${px} ${py}`
    const grow = v.grow ?? 1
    const even = Math.abs(sx - 1) < 1e-4 && Math.abs(sy - 1) < 1e-4
    const scaled = even
      ? grow === 1
        ? ""
        : grow.toFixed(4)
      : `${(grow * sx).toFixed(5)} ${(grow * sy).toFixed(5)}`
    // The frame that brings the host to rest is still drawn: a view that draws the pull itself (see `pulled`) must see it end.
    if (moved !== s.moved || scaled !== s.scaled) moving = true
    if (moved !== s.moved) host.style.translate = s.moved = moved
    if (scaled !== s.scaled) host.style.scale = s.scaled = scaled
    const at = v.pulled ?? (v.pulled = { x: 0, y: 0, sx: 1, sy: 1 })
    at.x = on ? s.x.x : 0
    at.y = on ? s.y.x : 0
    at.sx = even ? 1 : sx
    at.sy = even ? 1 : sy
    return moving
  }

  /** The way the cursor light comes from for a lens (uLightDir, as an angle), and how much the rim leans to it (uLightMix). */
  const aimOf = (m: GlassLens) => {
    const dx = pointer.x - m.screenX
    const dy = pointer.y - m.screenY
    const d = Math.hypot(dx, dy)
    // The light turns in half-degree steps (one step is less than a level of rim light on an
    // 8-bit screen), and stays put while it is off: a cursor moving far away, or over glass
    // without cursor light, leaves the frame as it is.
    const mix = m.cursorLight ? pointer.mix : 0
    const aim =
      mix > 0 && d > 0.5
        ? (Math.round(Math.atan2(dy, dx) * (360 / Math.PI)) * Math.PI) / 360
        : -Math.PI / 2
    return { aim, mix }
  }
  /** A glass's light of a press (LIGHT) as its shader takes it (uLight): centre and radius (canvas px, from the lens centre) and how white; null while it is out. */
  const shineOf = (
    lit: Lit,
    m: GlassLens
  ): [number, number, number, number] | null => {
    const shine = LIGHT.on && m.pointerLight !== false ? clamp(lit.glow.x) : 0
    if (shine <= 0) return null
    const pageL =
      0.2126 * m.surface[0] + 0.7152 * m.surface[1] + 0.0722 * m.surface[2]
    // (A press on a surface beside the control takes the surface's size, not the control's.)
    const side =
      lit.onBlob && lit.blob
        ? Math.max(lit.blob.hx, lit.blob.hy)
        : Math.max(m.hx, m.hy)
    const span = clamp(
      LIGHT.size * 2 * side,
      LIGHT.sizeMin,
      Math.max(LIGHT.sizeMin, LIGHT.sizeMax)
    )
    return [
      lit.x,
      lit.y,
      span,
      shine *
        clamp(
          lerp(LIGHT.strengthDark, LIGHT.strength, smooth(0.25, 0.6, pageL))
        ),
    ]
  }

  // Cohesion (COHESION): buttons near each other melt into one body. On a frame that changes a
  // button, every button on screen is measured as it is (its body on the page, and what its look
  // depends on), and each takes the ones within reach, nearest first, four at most. `nears` holds
  // what its shader is given for them (uNearâ¦ in FRAGMENT): NEAR_VALUES numbers (nine vec4) for each.
  type Melt = {
    v: GlassView
    m: GlassLens
    host: Element
    /** Screen px per canvas px, and the lens centre on screen (the canvas's own (cx, cy)). */
    g: number
    sx: number
    sy: number
    /** The body on screen: centre, half size, corner radius and the radius its bend follows (px). */
    x: number
    y: number
    hx: number
    hy: number
    r: number
    fr: number
    /** Its height at rest, and one of its design units, on screen (px). */
    rest: number
    du: number
  }
  const NEAR = 4
  const NEAR_NAMES = Array.from({ length: NEAR }, (_, i) =>
    [
      "uNear",
      "uNearShape",
      "uNearTint",
      "uNearLine",
      "uNearLook",
      "uNearShade",
      "uNearMirror",
      "uNearGlow",
      "uNearLight",
    ].map((name) => `${name}[${i}]`)
  )
  const NEAR_PAIR = Array.from({ length: NEAR }, (_, i) => `uNearPair[${i}]`)
  /** Per neighbour: its vec4s, then whether its canvas lies over this one's and how joined the two are. */
  const NEAR_VALUES = NEAR_NAMES[0].length * 4 + 2
  /** How much a lens mirrors of its surroundings (see `mirror` in `draw`): only clear glass does. */
  const mirrorOf = (m: GlassLens) =>
    m.refraction
      ? m.strength *
        Math.max(0, m.tune?.mirror ?? 1) *
        clamp((1 - m.refraction.frost) / 0.4)
      : 0
  /** How far into the glass the mirrored band goes, how far the rim looks, and how soft the picture is (CSS px; see uMirror.z, uReach and uSoft). */
  const mirrorShapeOf = (m: GlassLens) => {
    const reached = m.reflection
      ? clamp(
          m.reflection.height * MIRROR.reach,
          MIRROR.reachMin,
          Math.max(MIRROR.reachMin, MIRROR.reachMax)
        )
      : 0
    const deep =
      Math.max(0.01, MIRROR.depth) *
      Math.max(1, Math.min(m.hx, m.hy, reached || Infinity))
    return {
      deep,
      reach: mirrorOf(m) > 0 && m.reflection ? reached : 0,
      soft: Math.max(0, MIRROR.soft) * reached,
    }
  }
  const nears = new Map<GlassView, number[]>()
  /** The buttons that were on screen when they were last measured: one that comes or goes changes its neighbours. */
  let shownButtons = new Set<GlassView>()
  let meltsChanged = false
  const measure = (
    v: GlassView,
    m: GlassLens | null | undefined
  ): Melt | null => {
    const host = hostOf(v)
    if (!host || !m || m.width < 2 || m.height < 2) return null
    const g = m.scale && m.scale > 0 ? m.scale : 1
    const radius = Math.max(0, Math.min(m.radius, m.hx - 0.5, m.hy - 0.5))
    const band = m.refraction ? (m.band ?? 0) * m.unit : 0
    return {
      v,
      m,
      host,
      g,
      sx: m.screenX,
      sy: m.screenY,
      x: m.screenX + m.bodyX * g,
      y: m.screenY,
      hx: Math.max(m.hx, 0.5 * m.unit) * g,
      hy: Math.max(m.hy, 0.5 * m.unit) * g,
      r: radius * g,
      fr:
        Math.min(
          Math.max(radius, band),
          Math.max(0, Math.min(m.hx, m.hy) - 0.5)
        ) * g,
      rest: DESIGN_HEIGHT * m.unit * g,
      du: m.unit * g,
    }
  }
  /**
   * What glass `a` takes for its neighbour `b` (see uNearâ¦ in FRAGMENT), in a's design units, at
   * bridge softness `k` (screen px), the two `join`ed this much (0 = apart, 1 = one body for the light).
   */
  const nearValues = (
    a: Melt,
    b: Melt,
    k: number,
    join: number,
    out: number[]
  ) => {
    const to = 1 / a.du
    const m = b.m
    const r = m.refraction
    const width = m.border ? Math.max(0, m.borderWidth ?? 1) : 0
    const line = m.border ?? m.color
    out.push((b.x - a.sx) * to, (b.y - a.sy) * to, b.hx * to, b.hy * to)
    out.push(
      b.r * to,
      b.fr * to,
      Math.max(k * to, 1e-3),
      Math.max(m.bevel, 2) * b.du * to
    )
    out.push(m.color[0], m.color[1], m.color[2], r ? clamp(r.frost) : 0)
    out.push(
      line[0],
      line[1],
      line[2],
      width > 0 ? clamp(m.borderAlpha ?? 1) : 0
    )
    out.push(
      (r?.refract ?? 0) * b.du * to,
      r ? 1 : 0,
      width * b.g * to,
      aimOf(m).aim
    )
    out.push(
      m.shadow * m.strength,
      m.shadowSoftness * b.du * to,
      m.shadowOffset * b.du * to,
      b.du * to
    )
    const shapeB = mirrorShapeOf(m)
    const mine = mirrorOf(a.m)
    out.push(
      shapeB.deep * b.g * to,
      shapeB.reach * b.g * to,
      shapeB.soft * b.g * to,
      mine > 0 ? mirrorOf(m) / mine : 0
    )
    // Its light of a press, where it is on screen.
    const glow = m.glow ?? flashOf(b.v)
    if (glow)
      out.push(
        (b.sx + glow.x * b.g - a.sx) * to,
        (b.sy + glow.y * b.g - a.sy) * to,
        glow.r * b.g * to,
        Math.max(0, glow.amount)
      )
    else out.push(0, 0, 1, 0)
    const lit = lights.get(b.v)
    const light = lit ? shineOf(lit, m) : null
    if (light)
      out.push(
        (b.sx + light[0] * b.g - a.sx) * to,
        (b.sy + light[1] * b.g - a.sy) * to,
        light[2] * b.g * to,
        light[3]
      )
    else out.push(0, 0, 1, 0)
    // Glass later on the page is painted over glass before it.
    out.push(
      a.host.compareDocumentPosition(b.host) & Node.DOCUMENT_POSITION_FOLLOWING
        ? 1
        : 0,
      join
    )
  }
  /**
   * Measures every button on screen and works out each one's neighbours. `lensOf` holds the lenses
   * already read this frame; any other is read now. Returns the views whose neighbours (as their
   * shaders take them) changed, and those whose `near` changed, which must paint what lies behind again.
   */
  const cohere = (lensOf: Map<GlassView, GlassLens | null>) => {
    const pool: Melt[] = []
    const showing = new Set<GlassView>()
    for (const v of views) {
      if (v.button !== true || !v.visible) continue
      showing.add(v)
      let m = lensOf.get(v)
      if (m === undefined) lensOf.set(v, (m = v.lens(false)))
      const at = measure(v, m)
      if (at) pool.push(at)
    }
    shownButtons = showing
    const changed = new Set<GlassView>()
    const regrouped = new Set<GlassView>()
    const melted = new Set<GlassView>()
    for (const a of pool) {
      const found: { b: Melt; gap: number; k: number; join: number }[] = []
      for (const b of pool) {
        if (b === a || a.host.contains(b.host) || b.host.contains(a.host))
          continue
        const soft = cohesionSoftness(Math.min(a.rest, b.rest))
        if (soft <= 0) continue
        const gap = Math.max(
          Math.abs(b.x - a.x) - a.hx - b.hx,
          Math.abs(b.y - a.y) - a.hy - b.hy
        )
        // The bridge eases in as they near each other: none at `soft` apart, all of it at half that.
        const k = soft * (1 - smooth(0.5, 1, gap / soft))
        // Joined from the moment the bridge forms (half of `soft` apart), fully once it has some body
        // (a quarter of `soft` apart); for the light, by as much as COHESION.light lets it run on.
        if (k > 0.05)
          found.push({
            b,
            gap,
            k,
            join: (1 - smooth(soft / 4, soft / 2, gap)) * clamp(COHESION.light),
          })
      }
      found.sort((p, q) => p.gap - q.gap)
      const values: number[] = []
      const hosts: Element[] = []
      for (const { b, k, join } of found.slice(0, NEAR)) {
        nearValues(a, b, k, join, values)
        hosts.push(b.host)
      }
      const was = nears.get(a.v)
      if (
        (was?.length ?? 0) !== values.length ||
        values.some((x, i) => x !== was![i])
      )
        changed.add(a.v)
      if (values.length) {
        nears.set(a.v, values)
        melted.add(a.v)
      } else nears.delete(a.v)
      const before = a.v.near ?? []
      if (
        before.length !== hosts.length ||
        hosts.some((h) => !before.includes(h))
      ) {
        a.v.near = hosts.length ? hosts : undefined
        regrouped.add(a.v)
      }
    }
    // A button that has left the screen (or the page) melts into nothing any more.
    for (const v of [...nears.keys()]) {
      if (melted.has(v)) continue
      nears.delete(v)
      changed.add(v)
    }
    return { changed, regrouped }
  }

  const draw = (
    v: GlassView,
    refresh: boolean,
    repaint: boolean,
    read?: GlassLens | null
  ) => {
    const m = read !== undefined ? read : v.lens(refresh)
    let on = shown.get(v)
    if (!on) shown.set(v, (on = { sent: [], box: "" }))
    if (!m || m.width < 2 || m.height < 2) {
      v.ctx.clearRect(0, 0, v.canvas.width, v.canvas.height)
      on.sent.length = 0
      return
    }
    // The canvas's box is written only when it changes.
    const box = `${m.left}|${m.top}|${m.width}|${m.height}`
    if (box !== on.box) {
      on.box = box
      const st = v.canvas.style
      st.left = `${m.left}px`
      st.top = `${m.top}px`
      st.width = `${m.width}px`
      st.height = `${m.height}px`
    }
    const dpr = Math.min(window.devicePixelRatio || 1, 2)
    const devW = Math.max(2, Math.round(m.width * dpr))
    const devH = Math.max(2, Math.round(m.height * dpr))
    if (v.canvas.width !== devW || v.canvas.height !== devH) {
      v.canvas.width = devW
      v.canvas.height = devH
      on.sent.length = 0
    }

    // Nothing is asked of the GPU until this frame is known to differ from the one on the canvas:
    // the layers are painted here, on plain 2D canvases, and put into their textures at the end.
    const unit = m.unit
    const r = m.refraction
    /** The layers are the ones this view was last drawn with. */
    let fresh = true
    let p: Painted | undefined
    /** The layers painted on this frame, to upload. */
    let layers: Layers | undefined
    // A painter that takes only `back` has no front layer: none is cleared or uploaded.
    const fronted = !!r && r.paint.length > 1
    const skip = backSkipOf(m, dpr)
    if (r) {
      p = painted.get(v)
      if (!p)
        painted.set(
          v,
          (p = {
            back: { tex: null, w: 0, h: 0 },
            front: { tex: null, w: 0, h: 0 },
            w: 0,
            h: 0,
            skip: 0,
            at: 0,
          })
        )
      const now = performance.now()
      const sized = p.w === devW && p.h === devH && p.skip === skip
      fresh = !repaint && sized && now - p.at < REPAINT_EVERY
      if (!fresh) {
        // The page's picture, smaller where the frost never reads it at full size (BACK_SKIP),
        // and fitted to its canvas, so that it covers the glass's canvas exactly as before.
        const bw = skip ? Math.max(2, Math.ceil(devW / 2 ** skip)) : devW
        const bh = skip ? Math.max(2, Math.ceil(devH / 2 ** skip)) : devH
        const l = layersFor(bw, bh, fronted ? devW : 0, fronted ? devH : 0)
        l.back.ctx!.setTransform(1, 0, 0, 1, 0, 0)
        l.back.ctx!.clearRect(0, 0, bw, bh)
        if (skip)
          l.back.ctx!.setTransform(bw / m.width, 0, 0, bh / m.height, 0, 0)
        else l.back.ctx!.setTransform(dpr, 0, 0, dpr, 0, 0)
        if (fronted && l.front) {
          l.front.ctx!.setTransform(1, 0, 0, 1, 0, 0)
          l.front.ctx!.clearRect(0, 0, devW, devH)
          l.front.ctx!.setTransform(dpr, 0, 0, dpr, 0, 0)
        }
        // A painter that says nothing changed keeps the textures it already has.
        fresh = r.paint(l.back.ctx!, (l.front ?? front).ctx!) === false && sized
        if (!fresh) {
          layers = l
          p.w = devW
          p.h = devH
          p.skip = skip
          p.at = now
        }
      }
    }
    sent.length = names.length = sizes.length = 0
    // The surroundings, for the reflection. The picture is taken when it is first needed, and
    // again when sizes and colours are re-read or the canvas changes size, AROUND_EVERY apart at
    // most (a change that comes sooner waits its turn). A scroll takes none: what surrounds the
    // glass rides along. Until then the picture stays where it was taken, even if the canvas has
    // moved since.
    // Only clear glass mirrors: in full while its own colour covers it no more than a clear
    // button's tint does (0.6), less as the cover grows, and not at all once the glass is its
    // own colour (tinted glass, a lens frosted over at rest, a control painted in its fill).
    // Unlit glass mirrors nothing either. Glass that mirrors nothing takes no picture.
    const clear = r ? clamp((1 - r.frost) / 0.4) : 0
    const mirror = m.strength * Math.max(0, m.tune?.mirror ?? 1) * clear
    const f = mirror > 0 ? m.reflection : undefined
    if (refresh && m.reflection && !f) {
      const idle = mirrored.get(v)
      if (idle) idle.due = true
    }
    /** A picture of the surroundings taken on this frame, to upload. */
    let picture: Mirrored | undefined
    if (f) {
      let a = mirrored.get(v)
      if (!a)
        mirrored.set(
          v,
          (a = {
            pic: { tex: null, w: 0, h: 0 },
            w: 0,
            h: 0,
            at: 0,
            left: 0,
            top: 0,
            reach: 0,
            due: true,
            timer: 0,
            busy: false,
          })
        )
      const taken = a
      const reach = clamp(
        f.height * MIRROR.reach,
        MIRROR.reachMin,
        Math.max(MIRROR.reachMin, MIRROR.reachMax)
      )
      const aw = Math.max(2, Math.ceil((m.width + 2 * reach) * AROUND_SCALE))
      const ah = Math.max(2, Math.ceil((m.height + 2 * reach) * AROUND_SCALE))
      const now = performance.now()
      if (
        refresh ||
        (f.live && repaint) ||
        a.w !== aw ||
        a.h !== ah ||
        a.reach !== reach
      )
        a.due = true
      if (a.due && a.w && busy && !f.live && now - a.at < AROUND_WAIT) {
        // It waits for all to be still (see AROUND_WAIT): the picture it has is kept meanwhile.
        a.busy = true
      } else if (a.due && a.w && now - a.at < AROUND_EVERY) {
        if (!a.timer)
          a.timer = window.setTimeout(
            () => {
              taken.timer = 0
              if (mirrored.get(v) !== taken) return
              v.repaint = true
              wake()
            },
            AROUND_EVERY - (now - a.at)
          )
      } else if (a.due) {
        a.due = false
        if (around.canvas.width !== aw || around.canvas.height !== ah) {
          around.canvas.width = aw
          around.canvas.height = ah
        }
        const c = around.ctx!
        c.setTransform(1, 0, 0, 1, 0, 0)
        c.clearRect(0, 0, aw, ah)
        c.setTransform(
          AROUND_SCALE,
          0,
          0,
          AROUND_SCALE,
          reach * AROUND_SCALE,
          reach * AROUND_SCALE
        )
        f.paint(c, reach)
        picture = a
        a.w = aw
        a.h = ah
        a.at = now
        a.left = m.left
        a.top = m.top
        a.reach = reach
        pictured.push(a)
        fresh = false
      }
      set(
        "uAroundBox",
        (a.left - m.left - a.reach) / unit,
        (a.top - m.top - a.reach) / unit,
        a.w / AROUND_SCALE / unit,
        a.h / AROUND_SCALE / unit
      )
      set("uAroundScale", AROUND_SCALE * unit)
      set("uReach", reach / unit)
    } else {
      set("uAroundBox", 0, 0, 1, 1)
      set("uAroundScale", 1)
      set("uReach", 0)
    }
    set("uTextured", r ? 1 : 0)
    set("uRefract", r?.refract ?? 0)
    set("uMag", r?.magnify ?? 0)
    set("uDisp", r?.dispersion ?? 0)
    set("uBlurCenter", r?.blurCenter ?? 0)
    set("uBlurEdge", r?.blurEdge ?? 0)
    // Blur level follows screen density (reference: 2.27 device px per design unit).
    set("uBlurShift", Math.log2(Math.max((unit * dpr) / 2.27, 1e-3)))
    set("uFrost", r?.frost ?? 0)
    set("uBackSkip", skip)
    set("uFrostBlur", Math.max(0, r?.blur ?? 0) / unit)
    set("uFrostMix", clamp(r?.blurMix ?? 1))
    // Radial bend: a share of the viewport per axis, as the SVG card's map was.
    const radial = Math.max(0, r?.radial ?? 0)
    set(
      "uRadial",
      (radial * window.innerWidth) / unit,
      (radial * window.innerHeight) / unit
    )
    set("uCssPx", 1 / unit)
    set("uSize", devW, devH)
    set("uUnit", unit * dpr)
    set("uDevicePx", 1 / (unit * dpr))
    set("uCenter", m.cx / unit, m.cy / unit)
    set("uHalf", Math.max(m.hx / unit, 0.5), Math.max(m.hy / unit, 0.5))
    const radius = Math.max(
      0,
      Math.min(m.radius, m.hx - 0.5, m.hy - 0.5) / unit
    )
    set("uRadius", radius)
    const band = r ? (m.band ?? 0) : 0
    set("uBand", band)
    set(
      "uFieldRadius",
      Math.min(
        Math.max(radius, band),
        Math.max(0, (Math.min(m.hx, m.hy) - 0.5) / unit)
      )
    )
    set("uBodyX", m.bodyX / unit)
    set(
      "uDrop",
      (m.droplet?.x ?? 0) / unit,
      (m.droplet?.r ?? 0) / unit,
      (m.droplet?.k ?? 0) / unit
    )
    const blob = m.blob
    set(
      "uBlob",
      (blob?.x ?? 0) / unit,
      (blob?.y ?? 0) / unit,
      (blob?.hx ?? 0) / unit,
      (blob?.hy ?? 0) / unit
    )
    set("uBlobShape", (blob?.r ?? 0) / unit, (blob?.k ?? 0) / unit)
    set("uBlobNeck", (blob?.neck?.x ?? 0) / unit, (blob?.neck?.w ?? 0) / unit)
    set("uBlobFade", blob?.fade?.amount ?? 0, blob?.fade?.reach ?? 0.5)
    const mat = blob?.material
    set(
      "uBlobMat",
      clamp(mat?.frost ?? 0),
      Math.max(0, mat?.blur ?? 0) / unit,
      Math.max(0.05, mat?.bendCurve ?? 1.6),
      0.35 * Math.max(0.05, mat?.bendDepth ?? 1)
    )
    set(
      "uBlobLine",
      Math.max(0, mat?.borderWidth ?? 0) / unit,
      clamp(mat?.borderAlpha ?? 0),
      mat ? 1 : 0
    )
    set("uBevel", Math.max(m.bevel, 2))
    const k = m.tune ?? {}
    set("uRim", 0.55 * m.strength * (k.rim ?? 1))
    set("uCaustic", 0.08 * m.strength * (k.caustic ?? 1))
    set("uInner", 0.1 * m.strength * (k.inner ?? 1))
    set("uTopRefl", 0.3 * m.strength * (k.reflection ?? 1))
    set("uTopBase", 0.02 * m.strength * (k.reflection ?? 1))
    set("uRimWidth", Math.max(0.05, k.rimWidth ?? 1))
    set("uFresnel", 0.02 * (k.fresnel ?? 1))
    // The band is as deep as a share of the glass's shorter half, and of its reach on glass taller than that.
    const reached = m.reflection
      ? clamp(
          m.reflection.height * MIRROR.reach,
          MIRROR.reachMin,
          Math.max(MIRROR.reachMin, MIRROR.reachMax)
        )
      : 0
    const deep =
      (Math.max(0.01, MIRROR.depth) *
        Math.max(1, Math.min(m.hx, m.hy, reached || Infinity))) /
      unit
    set(
      "uMirror",
      clamp(MIRROR.line) * mirror,
      MIRROR.band * mirror,
      deep,
      clamp(MIRROR.dim)
    )
    set("uSoft", (Math.max(0, MIRROR.soft) * reached) / unit)
    const shares = Math.max(MIRROR.near + MIRROR.mid + MIRROR.far, 1e-3)
    set(
      "uSeen",
      MIRROR.near / shares,
      MIRROR.mid / shares,
      MIRROR.far / shares,
      Math.max(0, MIRROR.gain)
    )
    // The far side of the rim light takes the surroundings' colour on clear glass only.
    set("uBounce", Math.max(0, MIRROR.bounce), clamp(MIRROR.tint) * clear)
    set("uFall", Math.max(0.05, MIRROR.fall))
    set("uBendCurve", Math.max(0.05, k.bendCurve ?? 1.6))
    set("uEdgeBand", 0.35 * Math.max(0.05, k.bendDepth ?? 1))
    set("uSaturation", Math.max(0, k.saturation ?? 1))
    set("uFrostEdge", Math.max(0.05, k.frostEdge ?? 1))
    set("uShadow", m.shadow * m.strength)
    set("uShadowSoft", m.shadowSoftness)
    set("uShadowOffset", m.shadowOffset)
    set("uSurface", ...m.surface)
    set("uColor", ...m.color)
    set("uEdgeClear", m.edgeClear)
    set("uBorder", ...(m.border ?? m.color))
    set("uBorderWidth", m.border ? Math.max(0, m.borderWidth ?? 1) / unit : 0)
    set("uBorderAlpha", clamp(m.borderAlpha ?? 1))
    const { aim, mix: lightMix } = aimOf(m)
    set("uLightDir", Math.cos(aim), Math.sin(aim))
    set("uLightMix", lightMix)
    const glow = m.glow ?? flashOf(v)
    set(
      "uGlow",
      (glow?.x ?? 0) / unit,
      (glow?.y ?? 0) / unit,
      (glow?.r ?? 0) / unit,
      Math.max(0, glow?.amount ?? 0)
    )
    set(
      "uGlowHalo",
      glow?.halo ? (glow.halo.around === "blob" && blob ? 2 : 1) : 0,
      clamp(glow?.halo?.amount ?? 0)
    )
    set("uGlowBlob", clamp(glow?.blob ?? 1))
    // Pointer light: what the pointer is doing to this glass is worked out here, where the
    // glass's place on screen is fresh; the light itself is advanced once a frame (stepLight).
    let lit = lights.get(v)
    // A glass that continues another takes that one's light (see `lightOf`), measured from here.
    const shared =
      m.lightOf && m.lightOf !== v ? lights.get(m.lightOf) : undefined
    if (shared) {
      lit = {
        ...shared,
        x: shared.x + shared.sx - shared.bodyX - m.screenX,
        y: shared.y + shared.sy - m.screenY,
      }
    } else if (LIGHT.on && m.pointerLight !== false) {
      if (!lit) {
        const host = hostOf(v)
        lit = {
          glow: { x: 0, v: 0 },
          x: 0,
          y: 0,
          press: false,
          key: false,
          free: !!host && getComputedStyle(host).pointerEvents === "none",
          sx: 0,
          sy: 0,
          hx: 0,
          hy: 0,
          bodyX: 0,
          blob: null,
          onBlob: false,
        }
        lights.set(v, lit)
      }
      lit.sx = m.screenX + m.bodyX
      lit.sy = m.screenY
      lit.hx = m.hx
      lit.hy = m.hy
      lit.bodyX = m.bodyX
      lit.blob = blob
        ? { x: blob.x, y: blob.y, hx: blob.hx, hy: blob.hy }
        : null
      // A held pointer lights the glass it is on, or comes onto (a lens arriving under it), until it lets go.
      // The light stays at the point of the glass it began at: it does not follow the pointer.
      const press =
        lit.press || (beam.id !== -1 && under(v, lit) && innermost(v))
      if (press !== lit.press) {
        relit = true
        if (press) {
          lit.x = beam.x - m.screenX
          lit.y = beam.y - m.screenY
          lit.onBlob =
            onBlob(lit) &&
            (Math.abs(beam.x - lit.sx) > lit.hx ||
              Math.abs(beam.y - lit.sy) > lit.hy)
        }
      }
      lit.press = press
    }
    const light = lit ? shineOf(lit, m) : null
    if (light)
      set("uLight", light[0] / unit, light[1] / unit, light[2] / unit, light[3])
    else set("uLight", 0, 0, 1, 0)
    // The glass it melts into (COHESION), as its shader takes them (see uNear in FRAGMENT).
    const near = v.button === true && COHESION.on ? nears.get(v) : undefined
    const count = near ? Math.min(NEAR, near.length / NEAR_VALUES) : 0
    set("uNearCount", count)
    if (count) set("uNearFade", Math.max(0.01, COHESION.lightFade))
    for (let i = 0; i < count; i++) {
      const names = NEAR_NAMES[i]
      for (let j = 0; j < names.length; j++) {
        const at = i * NEAR_VALUES + j * 4
        set(names[j], near![at], near![at + 1], near![at + 2], near![at + 3])
      }
      set(
        NEAR_PAIR[i],
        near![i * NEAR_VALUES + NEAR_VALUES - 2],
        near![i * NEAR_VALUES + NEAR_VALUES - 1]
      )
    }
    // The same layers and the same uniforms as the frame on the canvas: nothing to draw.
    if (
      fresh &&
      on.sent.length === sent.length &&
      sent.every((value, i) => value === on.sent[i])
    )
      return
    on.sent = sent.slice()
    // The shared GL canvas only grows; each view is drawn into its bottom-left corner.
    if (glCanvas.width < devW || glCanvas.height < devH) {
      glCanvas.width = Math.max(glCanvas.width, devW)
      glCanvas.height = Math.max(glCanvas.height, devH)
    }
    gl.viewport(0, 0, devW, devH)
    // What lies beneath, what rides on top and what surrounds the glass: the pictures taken on
    // this frame are uploaded, the others are the ones this view already has.
    gl.activeTexture(gl.TEXTURE0)
    if (p && layers) upload(p.back, layers.back.canvas, true)
    else gl.bindTexture(gl.TEXTURE_2D, p?.back.tex ?? blank.back)
    gl.activeTexture(gl.TEXTURE1)
    if (p && layers?.front && fronted)
      upload(p.front, layers.front.canvas, false)
    else gl.bindTexture(gl.TEXTURE_2D, (fronted && p?.front.tex) || blank.front)
    gl.activeTexture(gl.TEXTURE2)
    if (picture) upload(picture.pic, around.canvas, true)
    else
      gl.bindTexture(
        gl.TEXTURE_2D,
        (f && mirrored.get(v)?.pic.tex) || blank.back
      )
    send()
    // The frost's own pass (FROST_PASS): on large, softly frosted glass the frost is drawn first,
    // into a smaller picture that the glass then reads.
    const sigma =
      r && !blob?.material
        ? Math.max(0, r.blur ?? 0) *
          Math.min(1, Math.max(0.05, k.frostEdge ?? 1)) *
          dpr
        : 0
    const texel =
      sigma >= FROST_PASS.sigma &&
      4 * m.hx * m.hy * dpr * dpr >= FROST_PASS.area
        ? Math.min(FROST_PASS.most, Math.floor(sigma / FROST_PASS.texel))
        : 0
    const fw = texel >= 2 ? Math.ceil(devW / texel) + 1 : 0
    const fh = texel >= 2 ? Math.ceil(devH / texel) + 1 : 0
    if (texel >= 2 && frostRoom(fw, fh)) {
      const sx = 1 / (texel * frostPic.w)
      const sy = 1 / (texel * frostPic.h)
      // The picture is not bound while it is drawn into.
      gl.activeTexture(gl.TEXTURE3)
      gl.bindTexture(gl.TEXTURE_2D, blank.front)
      gl.bindFramebuffer(gl.FRAMEBUFFER, frostPic.fbo)
      // Nothing of what it held is kept: a GPU that draws in tiles need not load it back.
      gl.invalidateFramebuffer(gl.FRAMEBUFFER, [gl.COLOR_ATTACHMENT0])
      gl.viewport(0, 0, fw, fh)
      gl.uniform4f(frostPassAt, 1, texel, sx, sy)
      gl.drawArrays(gl.TRIANGLES, 0, 3)
      gl.bindFramebuffer(gl.FRAMEBUFFER, null)
      gl.viewport(0, 0, devW, devH)
      gl.bindTexture(gl.TEXTURE_2D, frostPic.tex)
      gl.uniform4f(frostPassAt, 2, texel, sx, sy)
      frostPassHeld = 2
    } else if (frostPassHeld) {
      gl.uniform4f(frostPassAt, 0, 1, 0, 0)
      frostPassHeld = 0
    }
    gl.drawArrays(gl.TRIANGLES, 0, 3)
    v.ctx.clearRect(0, 0, devW, devH)
    v.ctx.drawImage(
      glCanvas,
      0,
      glCanvas.height - devH,
      devW,
      devH,
      0,
      0,
      devW,
      devH
    )
    v.drawn?.()
  }

  let raf = 0
  let last = 0
  const frame = (now: number) => {
    raf = 0
    if (dead) return
    const dt = last ? Math.min((now - last) / 1000, 1 / 30) : 1 / 60
    last = now
    const still = reduced.matches
    const target = pointer.active && !still ? 1 : 0
    const before = pointer.mix
    pointer.mix += (target - pointer.mix) * Math.min(1, dt * 6)
    if (Math.abs(pointer.mix - target) < 0.002) pointer.mix = target
    const relight = pointer.moved || pointer.mix !== before
    pointer.moved = false
    let running = pointer.mix !== target
    busy = ranLast || running
    // Buttons melt into each other (COHESION): they are drawn after the rest, once every one has
    // been measured, so each melts into the others as they are on this frame.
    const melting = COHESION.on
    if (!melting && nears.size) {
      for (const v of nears.keys()) {
        v.near = undefined
        v.dirty = true
      }
      nears.clear()
    }
    const due: { v: GlassView; refresh: boolean; repaint: boolean }[] = []
    let regroup = meltsChanged
    meltsChanged = false
    for (const v of views) {
      const stepped = v.step(dt, still)
      // After the view's own springs: its `grow` is this frame's.
      const pulled = stepPull(v, dt, still)
      const moving = stepped || pulled
      // (Both lights of a press: what a surface takes, and a button's flash.)
      const lit = stepLight(v, dt, still)
      const flashing = stepFlash(v, dt, still)
      const glowing = lit || flashing
      if (moving || glowing) running = busy = true
      const melts = melting && v.button === true
      if (melts && v.visible !== shownButtons.has(v)) regroup = true
      if (!v.visible) continue
      const again = v.repaint === true
      if (moving || glowing || v.dirty || again || relight) {
        const refresh = v.dirty
        v.dirty = false
        v.repaint = false
        // Only the light moved: the layers are as they were, so they are not painted again.
        if (melts) due.push({ v, refresh, repaint: moving || refresh || again })
        else draw(v, refresh, moving || refresh || again)
      }
    }
    if (melting && (due.length || regroup)) {
      const lensOf = new Map<GlassView, GlassLens | null>()
      for (const d of due) lensOf.set(d.v, d.v.lens(d.refresh))
      const { changed, regrouped } = cohere(lensOf)
      // A button whose neighbours moved is drawn again too; one that melts into other glass now (or
      // no longer) paints what lies behind it again, leaving that glass out (or taking it back in).
      for (const d of due)
        draw(d.v, d.refresh, d.repaint || regrouped.has(d.v), lensOf.get(d.v))
      for (const v of changed)
        if (v.visible && !due.some((d) => d.v === v))
          draw(v, false, regrouped.has(v), lensOf.get(v))
    }
    // A view may have woken the engine during this frame (a popup that has just gone back in
    // does): the next frame is then already asked for, and asking again would start a second
    // loop beside this one, for as long as anything on the page moves.
    // A draw found the pointer on (or off) some glass: its light starts on the next frame.
    if (relit) running = true
    relit = false
    // Pictures of the surroundings that waited while something moved or was lit (or were taken
    // then, having waited as long as they may) are taken once all is still, at once: the glass
    // that takes one is drawn again on the next frame.
    if (running) for (const a of pictured) a.busy = true
    pictured.length = 0
    ranLast = running
    if (running) wake()
    else {
      if (!raf) last = 0
      let again = false
      for (const [v, a] of mirrored) {
        if (!a.busy) continue
        a.busy = false
        a.due = true
        a.at = 0
        v.repaint = true
        again = true
      }
      if (again) wake()
    }
  }
  const wake = () => {
    if (!raf && !dead) raf = requestAnimationFrame(frame)
  }
  const invalidateAll = () => {
    for (const v of views) v.dirty = true
    wake()
  }

  window.addEventListener(
    "pointermove",
    (e) => {
      if (e.pointerType !== "mouse") return
      pointer.x = e.clientX
      pointer.y = e.clientY
      pointer.active = true
      pointer.moved = true
      wake()
    },
    { passive: true }
  )
  document.documentElement.addEventListener("pointerleave", () => {
    pointer.active = false
    pointer.moved = true
    wake()
  })
  // Pull (PULL): a press holds the innermost glass under it that asks to be pulled, and it is
  // followed over the whole window until it lets go.
  window.addEventListener(
    "pointerdown",
    (e) => {
      if (
        !PULL.on ||
        e.button !== 0 ||
        reduced.matches ||
        !(e.target instanceof Node) ||
        HANDED_ON.has(e)
      )
        return
      let held: GlassView | null = null
      let heldHost: HTMLElement | null = null
      for (const v of views) {
        const host = hostOf(v)
        if (
          v.pull !== true ||
          !host ||
          !host.contains(e.target) ||
          host.matches(':disabled, [data-disabled], [aria-disabled="true"]')
        )
          continue
        if (pulls.get(v)?.by) return
        if (!heldHost || heldHost.contains(host)) {
          held = v
          heldHost = host
        }
      }
      if (!held || !heldHost) return
      const p = pulledOf(held)
      // The host's own translate is read while the pull's is off it.
      if (!p.moved) {
        const own = getComputedStyle(heldHost).translate
        p.own = !own || own === "none" ? null : own.split(" ")
      }
      const at = restOf(heldHost, p)
      p.by = {
        id: e.pointerId,
        x: e.clientX,
        y: e.clientY,
        nowX: e.clientX,
        nowY: e.clientY,
        cx: at.x,
        cy: at.y,
        lastX: at.x,
        lastY: at.y,
        size: Math.max(heldHost.offsetWidth, heldHost.offsetHeight),
      }
      p.driftX = p.driftY = 0
      held.held = true
      wake()
    },
    { passive: true, capture: true }
  )
  window.addEventListener(
    "pointermove",
    (e) => {
      for (const p of pulls.values()) {
        if (p.by?.id !== e.pointerId) continue
        p.by.nowX = e.clientX
        p.by.nowY = e.clientY
        wake()
      }
    },
    { passive: true, capture: true }
  )
  const unhold = (e: PointerEvent) => {
    for (const [v, p] of pulls) {
      if (p.by?.id !== e.pointerId) continue
      letGo(v, p)
      wake()
    }
  }
  window.addEventListener("pointerup", unhold, { passive: true, capture: true })
  window.addEventListener("pointercancel", unhold, {
    passive: true,
    capture: true,
  })
  // Pointer light (LIGHT): where the lighting pointer is, what it is over and whether it is held.
  // Which glass that lights is decided when each glass is drawn, so every change asks for a frame.
  const lightMoved = () => {
    pointer.moved = true
    wake()
  }
  window.addEventListener(
    "pointermove",
    (e) => {
      // Only the held pointer counts (a lens may come under it): one that moves over the page without pressing asks for nothing.
      if (!LIGHT.on || e.pointerId !== beam.id) return
      beam.x = e.clientX
      beam.y = e.clientY
      beam.over = e.target
      lightMoved()
    },
    { passive: true, capture: true }
  )
  window.addEventListener(
    "pointerdown",
    (e) => {
      if (!LIGHT.on || e.button !== 0 || HANDED_ON.has(e)) return
      beam.x = e.clientX
      beam.y = e.clientY
      beam.over = e.target
      beam.id = e.pointerId
      lightMoved()
    },
    { passive: true, capture: true }
  )
  const lift = (e: PointerEvent) => {
    if (e.pointerId !== beam.id) return
    beam.id = -1
    for (const s of lights.values()) s.press = false
    lightMoved()
  }
  window.addEventListener("pointerup", lift, { passive: true, capture: true })
  window.addEventListener("pointercancel", lift, {
    passive: true,
    capture: true,
  })
  // A button's flash (GLOW): a press lights the innermost button under it where it lands, and
  // holds it until that pointer lets go; Space or Enter lights the focused button's centre.
  window.addEventListener(
    "pointerdown",
    (e) => {
      if (e.button !== 0 || HANDED_ON.has(e) || !(e.target instanceof Node))
        return
      // A choice pressed inside a surface lights that surface around it.
      const choice =
        e.target instanceof Element
          ? e.target.closest<HTMLElement>(CHOICES)
          : null
      const chosen =
        choice && !choice.matches('[data-disabled], [aria-disabled="true"]')
          ? choice
          : null
      let hit: GlassView | null = null
      let hitHost: HTMLElement | null = null
      for (const v of views) {
        const host = hostOf(v)
        if (
          !host ||
          host.matches(':disabled, [data-disabled], [aria-disabled="true"]')
        )
          continue
        if (
          v.button === true
            ? !(v.pressArea ?? host).contains(e.target)
            : !chosen ||
              v.choices === false ||
              !v.visible ||
              !host.contains(chosen)
        )
          continue
        if (!hitHost || hitHost.contains(host)) {
          hit = v
          hitHost = host
        }
      }
      const f =
        hit &&
        flash(
          hit,
          e.clientX,
          e.clientY,
          hit.button === true ? undefined : (chosen ?? undefined)
        )
      if (f) f.by = e.pointerId
    },
    { passive: true, capture: true }
  )
  const unflash = (e: PointerEvent) => {
    for (const f of flashes.values()) {
      if (f.by !== e.pointerId) continue
      f.by = -1
      wake()
    }
  }
  window.addEventListener("pointerup", unflash, {
    passive: true,
    capture: true,
  })
  window.addEventListener("pointercancel", unflash, {
    passive: true,
    capture: true,
  })
  const flashKey = (e: KeyboardEvent) => {
    if (e.key !== " " && e.key !== "Enter") return
    const down = e.type === "keydown"
    if (down && e.repeat) return
    if (!down) {
      for (const f of flashes.values()) f.key = false
      return wake()
    }
    const focused = document.activeElement
    if (!focused) return
    // On a surface, the key chooses the focused choice: the light starts at its middle.
    const choice = focused.closest<HTMLElement>(CHOICES)
    const chosen =
      choice && !choice.matches('[data-disabled], [aria-disabled="true"]')
        ? choice
        : null
    let surface: GlassView | null = null
    let surfaceHost: HTMLElement | null = null
    for (const v of views) {
      const host = hostOf(v)
      if (
        !host ||
        host.matches(':disabled, [data-disabled], [aria-disabled="true"]')
      )
        continue
      if (v.button === true) {
        if (!focused.contains(v.canvas)) continue
        const f = flash(v)
        if (f) f.key = true
      } else if (
        chosen &&
        v.choices !== false &&
        v.visible &&
        host.contains(chosen) &&
        (!surfaceHost || surfaceHost.contains(host))
      ) {
        surface = v
        surfaceHost = host
      }
    }
    if (surface && chosen) {
      const r = chosen.getBoundingClientRect()
      const f = flash(
        surface,
        r.left + r.width / 2,
        r.top + r.height / 2,
        chosen
      )
      if (f) f.key = true
    }
    wake()
  }
  window.addEventListener("keydown", flashKey, true)
  window.addEventListener("keyup", flashKey, true)
  window.addEventListener(
    "focusout",
    () => {
      for (const f of flashes.values()) f.key = false
      wake()
    },
    true
  )
  // Space or Enter on the focused control lights the middle of its glass while the key is down.
  const key = (e: KeyboardEvent) => {
    if (e.key !== " " && e.key !== "Enter") return
    const down = e.type === "keydown"
    if (down && (!LIGHT.on || e.repeat)) return
    const focused = document.activeElement
    for (const [v, s] of lights) {
      const held = down && !s.free && !!focused && focused.contains(v.canvas)
      if (held && !s.key && !s.press) {
        s.x = s.bodyX
        s.y = 0
      }
      s.key = held
    }
    wake()
  }
  window.addEventListener("keydown", key, true)
  window.addEventListener("keyup", key, true)
  window.addEventListener(
    "focusout",
    () => {
      for (const s of lights.values()) s.key = false
      wake()
    },
    true
  )
  // Theme switches (class="dark", data-theme, color-scheme) re-read every colour.
  new MutationObserver(invalidateAll).observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["class", "data-theme", "style"],
  })
  new MutationObserver(invalidateAll).observe(document.body, {
    attributes: true,
    attributeFilter: ["data-theme"],
    subtree: true,
  })
  window
    .matchMedia("(prefers-color-scheme: dark)")
    .addEventListener("change", invalidateAll)
  // A radial bend scales with the viewport.
  window.addEventListener("resize", invalidateAll, { passive: true })
  glCanvas.addEventListener("webglcontextlost", () => {
    dead = true
    for (const v of views) {
      v.lost()
      v.ctx.clearRect(0, 0, v.canvas.width, v.canvas.height)
    }
    // No frame comes after this: the hosts get back what the engine wrote on them.
    for (const [v, p] of pulls) {
      const host = hostOf(v)
      v.held = false
      if (host && p.moved) host.style.translate = ""
      if (host && p.scaled) host.style.scale = ""
    }
    pulls.clear()
    engine = undefined
  })

  return {
    add: (v) => {
      views.add(v)
      meltsChanged = true
      wake()
    },
    remove: (v) => {
      views.delete(v)
      lights.delete(v)
      flashes.delete(v)
      // The glass that melted into it lets go.
      if (v.button === true) {
        meltsChanged = true
        wake()
      }
      nears.delete(v)
      shownButtons.delete(v)
      v.near = undefined
      const pulled = pulls.get(v)
      if (pulled) {
        pulls.delete(v)
        v.held = false
        const host = hostOf(v)
        if (host && pulled.moved) host.style.translate = ""
        if (host && pulled.scaled) host.style.scale = ""
      }
      const a = mirrored.get(v)
      if (a) {
        mirrored.delete(v)
        clearTimeout(a.timer)
        gl.deleteTexture(a.pic.tex)
      }
      const p = painted.get(v)
      if (!p) return
      painted.delete(v)
      gl.deleteTexture(p.back.tex)
      gl.deleteTexture(p.front.tex)
    },
    wake,
    resolveColor,
  }
}

let engine: GlassEngine | null | undefined

/** The shared engine (created on first use, client only). `null` = no WebGL2: use the CSS look. */
export function getGlassEngine(): GlassEngine | null {
  if (typeof window === "undefined") return null
  if (engine === undefined) engine = createEngine()
  return engine
}

// dom-snapshot â paints a DOM subtree into a Canvas2D context at its on-screen position.
//
// A WebGL lens cannot read the page's pixels, so glass that bends the page needs the
// page as a texture. This paints a good-enough picture of it: backgrounds (colours,
// gradients and images, with their size, position and repeat), rounded borders, text,
// inline SVG icons, canvases, images and video (with object-fit) and backdrop blur.
// Siblings are painted in CSS order: negative z-index, content, positioned, positive z-index.
// It is not a browser renderer: no shadows, conic gradients, masks, rotation or
// ::before/::after. An image from another origin is requested again with CORS; if its
// server does not allow that it is left out, because a canvas such an image has touched
// can never become a WebGL texture. Used by `material="clear"` glass, by GlassBadge and,
// through `drawAround`, for what every rim mirrors of the page around it.
//
// COPY THIS FILE VERBATIM. MIT â https://github.com/bilalgursen/liquid-glass

type Box = { x: number; y: number; w: number; h: number }
type Drawable = HTMLImageElement | HTMLCanvasElement | HTMLVideoElement

const isVisibleColor = (color: string) =>
  !!color &&
  color !== "transparent" &&
  !/rgba\(.*,\s*0\)$/.test(color) &&
  !/\/\s*0\)$/.test(color)

/** Splits on a separator that is not inside parentheses: "a(1, 2), b" â ["a(1, 2)", "b"]. */
function splitTop(text: string, separator: string) {
  const parts: string[] = []
  let depth = 0
  let start = 0
  for (let i = 0; i < text.length; i++) {
    const ch = text[i]
    if (ch === "(") depth++
    else if (ch === ")") depth--
    else if (ch === separator && depth === 0) {
      parts.push(text.slice(start, i))
      start = i + 1
    }
  }
  parts.push(text.slice(start))
  return parts.map((part) => part.trim()).filter(Boolean)
}

/** "40%" or "12px" of a span. */
const lengthOf = (token: string, span: number) =>
  token.endsWith("%")
    ? (span * parseFloat(token)) / 100
    : parseFloat(token) || 0

/** One axis of a CSS position ("25%", "12px", "right", "calc(100% - 8px)") inside `free` px of room. */
function along(token: string | undefined, free: number) {
  if (!token) return free / 2
  const calc = /^calc\(([-\d.]+)% ([+-]) ([\d.]+)px\)$/.exec(token)
  if (calc)
    return (
      (free * Number(calc[1])) / 100 +
      (calc[2] === "-" ? -1 : 1) * Number(calc[3])
    )
  if (/^-?[\d.]/.test(token)) return lengthOf(token, free)
  return token === "left" || token === "top"
    ? 0
    : token === "right" || token === "bottom"
      ? free
      : free / 2
}

/** `background-position`, `object-position` and a gradient's `at â¦` as an offset into the free room. */
function placeOf(
  position: string,
  freeX: number,
  freeY: number
): [number, number] {
  let [a, b, c, d] = splitTop(position, " ")
  // "right 10px bottom 20px": offsets measured from the named edges.
  if (d)
    return [
      a === "right" ? freeX - along(b, freeX) : along(b, freeX),
      c === "bottom" ? freeY - along(d, freeY) : along(d, freeY),
    ]
  if (a === "top" || a === "bottom" || b === "left" || b === "right")
    [a, b] = [b, a]
  return [along(a, freeX), along(b, freeY)]
}

// ââ Sources: loading, and keeping the canvas readable ââââââââââââââââââââââââ

const verdicts = new WeakMap<Drawable, { key: string; ok: boolean }>()

/**
 * Is this source safe to draw? One image without CORS (or an SVG, in some browsers)
 * taints the whole canvas and WebGL can then no longer read it, so each source is
 * tried once on a 1Ã1 canvas first. `key` is whatever makes it a different picture.
 */
function isClean(source: Drawable, key = "") {
  const known = verdicts.get(source)
  if (known && known.key === key) return known.ok
  let ok = false
  try {
    const probe = document.createElement("canvas")
    probe.width = probe.height = 1
    const ctx = probe.getContext("2d", { willReadFrequently: true })
    if (ctx) {
      ctx.drawImage(source, 0, 0, 1, 1)
      ctx.getImageData(0, 0, 1, 1)
      ok = true
    }
  } catch {
    // SecurityError: another origin without CORS. InvalidStateError: a broken image.
  }
  verdicts.set(source, { key, ok })
  return ok
}

const waiting = new WeakMap<HTMLImageElement, Set<() => void>>()

/** True once the image can be drawn. Until then `onStale` is called when it arrives. */
function isLoaded(image: HTMLImageElement, onStale?: () => void) {
  if (image.complete) return image.naturalWidth > 0
  if (!onStale) return false
  let callbacks = waiting.get(image)
  if (!callbacks) {
    const pending = (callbacks = new Set())
    waiting.set(image, pending)
    image.addEventListener(
      "load",
      () => {
        waiting.delete(image)
        pending.forEach((notify) => notify())
      },
      { once: true }
    )
  }
  callbacks.add(onStale)
  return false
}

const isSameOrigin = (src: string) => {
  try {
    const url = new URL(src, location.href)
    return (
      url.protocol === "data:" ||
      url.protocol === "blob:" ||
      url.origin === location.origin
    )
  } catch {
    return false
  }
}

const copies = new Map<string, HTMLImageElement>()

/** Our own copy of an image by URL: a CSS background, or an <img> the page loaded without CORS. */
function imageCopy(src: string) {
  let image = copies.get(src)
  if (!image) {
    if (copies.size > 200) copies.clear()
    image = new Image()
    if (!isSameOrigin(src)) image.crossOrigin = "anonymous"
    image.decoding = "async"
    image.src = src
    copies.set(src, image)
  }
  return image
}

/** Draws an image or a video frame into its box the way `object-fit` and `object-position` place it. */
function drawFitted(
  ctx: CanvasRenderingContext2D,
  source: Drawable,
  sw: number,
  sh: number,
  box: Box,
  radius: number,
  style: CSSStyleDeclaration
) {
  const fit = style.objectFit
  let w = box.w
  let h = box.h
  if (fit !== "fill") {
    const contain = Math.min(box.w / sw, box.h / sh)
    const k =
      fit === "cover"
        ? Math.max(box.w / sw, box.h / sh)
        : fit === "none"
          ? 1
          : fit === "scale-down"
            ? Math.min(1, contain)
            : contain
    w = sw * k
    h = sh * k
  }
  const [ox, oy] = placeOf(style.objectPosition, box.w - w, box.h - h)
  const clips = radius > 0 || w > box.w + 0.5 || h > box.h + 0.5
  if (clips) {
    ctx.save()
    ctx.beginPath()
    ctx.roundRect(box.x, box.y, box.w, box.h, radius)
    ctx.clip()
  }
  ctx.drawImage(source, box.x + ox, box.y + oy, w, h)
  if (clips) ctx.restore()
}

const svgCache = new WeakMap<
  Element,
  { key: string; image: HTMLImageElement }
>()
/** Set when this browser treats an SVG image as unreadable: icons are then left out. */
let svgTaints = false

/**
 * Draws an inline SVG as an image. Colours that come from classes are inlined first.
 * Built once per element and rebuilt when the colour, the cache key or the size
 * changes, so an animated SVG keeps its first frame instead of rebuilding every call.
 */
function drawSvg(
  ctx: CanvasRenderingContext2D,
  svg: SVGSVGElement,
  color: string,
  box: Box,
  onStale: (() => void) | undefined,
  cacheKey: string
) {
  if (svgTaints) return
  const key = `${color}|${cacheKey}|${Math.round(box.w)}x${Math.round(box.h)}`
  let entry = svgCache.get(svg)
  if (!entry || entry.key !== key) {
    const clone = svg.cloneNode(true) as SVGSVGElement
    const originals = [svg, ...svg.querySelectorAll("*")]
    const clones = [clone, ...clone.querySelectorAll("*")]
    originals.forEach((original, i) => {
      const style = getComputedStyle(original)
      const target = clones[i] as SVGElement
      target.removeAttribute("class")
      target.style.fill = style.fill
      target.style.stroke = style.stroke
      target.style.animation = "none"
    })
    clone.setAttribute("xmlns", "http://www.w3.org/2000/svg")
    clone.setAttribute("width", String(box.w))
    clone.setAttribute("height", String(box.h))
    clone.style.color = color
    const image = new Image()
    image.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(new XMLSerializer().serializeToString(clone))}`
    entry = { key, image }
    svgCache.set(svg, entry)
  }
  if (!isLoaded(entry.image, onStale)) return
  if (isClean(entry.image))
    ctx.drawImage(entry.image, box.x, box.y, box.w, box.h)
  else svgTaints = true
}

// ââ Backgrounds: gradients and images ââââââââââââââââââââââââââââââââââââââââ

type Stop = { color: string; at: number | null; px: boolean }
type Gradient =
  | {
      kind: "linear"
      repeating: boolean
      stops: Stop[]
      angle: number
      corner: string
    }
  | {
      kind: "radial"
      repeating: boolean
      stops: Stop[]
      circle: boolean
      extent: string
      size: string[]
      at: string
    }
type BackgroundImage = { kind: "url"; src: string } | Gradient

function parseStops(args: string[], currentColor: string): Stop[] | null {
  const stops: Stop[] = []
  for (const arg of args) {
    const tokens = splitTop(arg, " ")
    const positions: string[] = []
    while (tokens.length && /^-?[\d.]+(%|px)$/.test(tokens[tokens.length - 1]))
      positions.unshift(tokens.pop() as string)
    if (!tokens.length) continue // a colour hint (a position alone) is skipped
    const color = tokens.join(" ").replace(/currentcolor/gi, currentColor)
    if (!positions.length) stops.push({ color, at: null, px: false })
    for (const position of positions)
      stops.push({
        color,
        at: parseFloat(position),
        px: position.endsWith("px"),
      })
  }
  return stops.length > 1 ? stops : null
}

/** One layer of a computed `background-image`; null for what is not supported (conic gradients, image-setâ¦). */
function parseImage(
  text: string,
  currentColor: string
): BackgroundImage | null {
  const url = /^url\((['"]?)(.*)\1\)$/.exec(text)
  if (url) return { kind: "url", src: url[2] }
  const gradient = /^(repeating-)?(linear|radial)-gradient\(([\s\S]*)\)$/.exec(
    text
  )
  if (!gradient) return null
  const repeating = !!gradient[1]
  const args = splitTop(gradient[3], ",")
  // The first argument is the direction or the shape, unless it is already a colour.
  // "in oklab" (the interpolation space) is dropped: canvas always blends in sRGB.
  const first = args[0] ?? ""
  const head = first.replace(/\bin\s+[\w-]+(\s+\w+\s+hue)?/i, "").trim()
  const spaceOnly = head === "" && first !== ""
  if (gradient[2] === "linear") {
    let angle = Math.PI
    let corner = ""
    let isDirection = spaceOnly
    if (/^to\s/.test(head)) {
      const v = /top/.test(head) ? "t" : /bottom/.test(head) ? "b" : ""
      const hz = /left/.test(head) ? "l" : /right/.test(head) ? "r" : ""
      if (v && hz) corner = v + hz
      else
        angle =
          (
            { t: 0, r: Math.PI / 2, b: Math.PI, l: Math.PI * 1.5 } as Record<
              string,
              number
            >
          )[v || hz] ?? Math.PI
      isDirection = true
    } else if (/^-?[\d.]+(deg|grad|rad|turn)$/.test(head)) {
      const n = parseFloat(head)
      angle = head.endsWith("turn")
        ? n * Math.PI * 2
        : head.endsWith("grad")
          ? (n * Math.PI) / 200
          : head.endsWith("rad")
            ? n
            : (n * Math.PI) / 180
      isDirection = true
    }
    const stops = parseStops(isDirection ? args.slice(1) : args, currentColor)
    return stops && { kind: "linear", repeating, stops, angle, corner }
  }
  const isShape =
    spaceOnly ||
    /^(circle|ellipse|closest-|farthest-|at\s|-?[\d.]+(px|%))/.test(head)
  const [shape = "", at = "center"] = isShape ? head.split(/\s*\bat\s+/) : []
  const size = shape.match(/-?[\d.]+(px|%)/g) ?? []
  const stops = parseStops(isShape ? args.slice(1) : args, currentColor)
  return (
    stops && {
      kind: "radial",
      repeating,
      stops,
      circle: /circle/.test(shape) || size.length === 1,
      extent:
        /(closest|farthest)-(side|corner)/.exec(shape)?.[0] ??
        "farthest-corner",
      size,
      at,
    }
  )
}

const parsed = new Map<string, (BackgroundImage | null)[]>()

function imagesOf(style: CSSStyleDeclaration) {
  const value = style.backgroundImage
  const key = /currentcolor/i.test(value) ? `${value}|${style.color}` : value
  let images = parsed.get(key)
  if (!images) {
    if (parsed.size > 300) parsed.clear()
    images = splitTop(value, ",").map((image) => parseImage(image, style.color))
    parsed.set(key, images)
  }
  return images
}

/** A stop's colour at zero alpha. CSS fades in premultiplied colour, canvas does not, so "transparent" has to keep the hue next to it. */
function clearOf(color: string) {
  const legacy = /^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/.exec(color)
  if (legacy) return `rgba(${legacy[1]}, ${legacy[2]}, ${legacy[3]}, 0)`
  const modern = /^([a-z-]+\([^/)]+?)\s*(\/[^)]*)?\)$/.exec(color)
  return modern ? `${modern[1]} / 0)` : color
}

/**
 * Resolves stop positions along a gradient line `length` px long. Returns the part of
 * the line the stops span (`from`..`to`, as fractions of it) and each stop inside that
 * part (0..1). `reach`: how far along the line the box extends (repeats cover it).
 */
function rampOf(stops: Stop[], length: number, repeating: boolean, reach = 1) {
  const at = stops.map((stop) =>
    stop.at === null
      ? null
      : stop.px
        ? stop.at / Math.max(length, 1e-6)
        : stop.at / 100
  )
  if (at[0] === null) at[0] = 0
  if (at[at.length - 1] === null) at[at.length - 1] = 1
  for (let i = 1; i < at.length; i++) {
    if (at[i] === null) {
      // Stops without a position are spread evenly between their neighbours.
      let j = i
      while (at[j] === null) j++
      const a = at[i - 1] as number
      const b = Math.max(at[j] as number, a)
      for (let k = i; k < j; k++)
        at[k] = a + ((b - a) * (k - i + 1)) / (j - i + 1)
    }
    at[i] = Math.max(at[i] as number, at[i - 1] as number)
  }
  let list: [number, string][] = []
  stops.forEach((stop, i) => {
    const p = at[i] as number
    const before = stops[i - 1]
    const after = stops[i + 1]
    // A transparent stop becomes its neighbours' colours at zero alpha (see clearOf).
    const fades = !isVisibleColor(stop.color)
    const fromBefore = fades && !!before && isVisibleColor(before.color)
    const toAfter = fades && !!after && isVisibleColor(after.color)
    if (fromBefore) list.push([p, clearOf(before.color)])
    if (toAfter) list.push([p, clearOf(after.color)])
    if (!fromBefore && !toAfter) list.push([p, stop.color])
  })
  let from = list[0][0]
  let to = list[list.length - 1][0]
  const period = to - from
  if (repeating && period > 1e-4) {
    const first = Math.floor(-from / period)
    const count = Math.ceil((reach - from) / period) - first
    if (count > 200) return null
    const one = list
    list = []
    for (let k = first; k < first + count; k++)
      for (const [p, color] of one) list.push([p + k * period, color])
    from += first * period
    to = from + count * period
  }
  // Stops that all share one position are a hard edge: keep the line a hair long, or canvas paints nothing.
  const span = Math.max(to - from, 0.02 / Math.max(length, 1e-6))
  return {
    from,
    to: from + span,
    stops: list.map(([p, color]): [number, string] => [
      Math.min(1, Math.max(0, (p - from) / span)),
      color,
    ]),
  }
}

/** Fills (0, 0, w, h) with a CSS gradient. */
function fillGradient(
  ctx: CanvasRenderingContext2D,
  gradient: Gradient,
  w: number,
  h: number
) {
  if (gradient.kind === "linear") {
    let angle = gradient.angle
    if (gradient.corner) {
      // "to top right": the line that puts the two neighbouring corners on the 50 % mark.
      const base = Math.atan2(h, w)
      angle =
        (
          {
            tr: base,
            br: Math.PI - base,
            bl: Math.PI + base,
            tl: -base,
          } as Record<string, number>
        )[gradient.corner] ?? base
    }
    const sin = Math.sin(angle)
    const cos = Math.cos(angle)
    const length = Math.abs(w * sin) + Math.abs(h * cos)
    const ramp = rampOf(gradient.stops, length, gradient.repeating)
    if (!ramp) return
    // The gradient line runs through the centre of the box.
    const x = (t: number) => w / 2 + sin * length * (t - 0.5)
    const y = (t: number) => h / 2 - cos * length * (t - 0.5)
    const fill = ctx.createLinearGradient(
      x(ramp.from),
      y(ramp.from),
      x(ramp.to),
      y(ramp.to)
    )
    for (const [p, color] of ramp.stops) fill.addColorStop(p, color)
    ctx.fillStyle = fill
    ctx.fillRect(0, 0, w, h)
    return
  }
  const [cx, cy] = placeOf(gradient.at, w, h)
  const dx = [Math.abs(cx), Math.abs(w - cx)]
  const dy = [Math.abs(cy), Math.abs(h - cy)]
  const pick = gradient.extent.startsWith("closest") ? Math.min : Math.max
  let rx = pick(...dx)
  let ry = pick(...dy)
  if (gradient.size.length) {
    rx = lengthOf(gradient.size[0], w)
    ry = gradient.size[1] ? lengthOf(gradient.size[1], h) : rx
  } else if (gradient.circle)
    rx = ry = gradient.extent.endsWith("corner")
      ? Math.hypot(rx, ry)
      : pick(rx, ry)
  else if (gradient.extent.endsWith("corner")) {
    rx *= Math.SQRT2
    ry *= Math.SQRT2
  }
  if (rx < 0.01 || ry < 0.01) return
  const ramp = rampOf(
    gradient.stops,
    rx,
    gradient.repeating,
    Math.hypot(Math.max(...dx) / rx, Math.max(...dy) / ry)
  )
  if (!ramp) return
  const inner = Math.max(0, rx * ramp.from)
  const fill = ctx.createRadialGradient(
    0,
    0,
    inner,
    0,
    0,
    Math.max(rx * ramp.to, inner + 1e-3)
  )
  for (const [p, color] of ramp.stops) fill.addColorStop(p, color)
  // An ellipse is a circle squeezed along y.
  ctx.save()
  ctx.translate(cx, cy)
  ctx.scale(1, ry / rx)
  ctx.fillStyle = fill
  ctx.fillRect(-cx, (-cy * rx) / ry, w, (h * rx) / ry)
  ctx.restore()
}

/**
 * Paints an element's `background-image` layers. `area` is the box they are sized and
 * positioned in, `bounds` the part of it worth painting. The caller has clipped to the box.
 */
function paintBackgrounds(
  ctx: CanvasRenderingContext2D,
  style: CSSStyleDeclaration,
  area: Box,
  bounds: Box,
  onStale?: () => void
) {
  const images = imagesOf(style)
  const sizes = splitTop(style.backgroundSize, ",")
  const positions = splitTop(style.backgroundPosition, ",")
  const repeats = splitTop(style.backgroundRepeat, ",")
  // The first layer is the top one: paint from the last.
  for (let n = images.length - 1; n >= 0; n--) {
    const image = images[n]
    if (!image) continue
    let source: HTMLImageElement | null = null
    let tw = area.w
    let th = area.h
    if (image.kind === "url") {
      source = imageCopy(image.src)
      if (!isLoaded(source, onStale) || !isClean(source)) continue
      tw = source.naturalWidth
      th = source.naturalHeight
    }
    // Tile size: gradients have no size of their own and fill the area.
    const size = sizes[n % sizes.length] ?? "auto"
    if (size === "cover" || size === "contain") {
      const k = (size === "cover" ? Math.max : Math.min)(
        area.w / tw,
        area.h / th
      )
      tw *= k
      th *= k
    } else {
      const [sw = "auto", sh = "auto"] = splitTop(size, " ")
      const ratio = tw / th
      if (sw !== "auto") tw = lengthOf(sw, area.w)
      if (sh !== "auto") th = lengthOf(sh, area.h)
      if (source && sw !== "auto" && sh === "auto") th = tw / ratio
      if (source && sw === "auto" && sh !== "auto") tw = th * ratio
    }
    if (!(tw >= 0.5 && th >= 0.5)) continue
    const [ox, oy] = placeOf(
      positions[n % positions.length] ?? "0% 0%",
      area.w - tw,
      area.h - th
    )
    const repeat = repeats[n % repeats.length] ?? "repeat"
    const [repeatX, repeatY = repeatX] = repeat.split(" ")
    const tilesX = repeat !== "repeat-y" && repeatX !== "no-repeat"
    const tilesY = repeat !== "repeat-x" && repeatY !== "no-repeat"
    // Only the tiles that reach the visible part.
    const x0 = area.x + ox
    const y0 = area.y + oy
    const i0 = tilesX ? Math.floor((bounds.x - x0) / tw) : 0
    const i1 = tilesX ? Math.floor((bounds.x + bounds.w - x0 - 0.01) / tw) : 0
    const j0 = tilesY ? Math.floor((bounds.y - y0) / th) : 0
    const j1 = tilesY ? Math.floor((bounds.y + bounds.h - y0 - 0.01) / th) : 0
    // A very fine pattern blurs to nothing under glass: not worth hundreds of tiles.
    if ((i1 - i0 + 1) * (j1 - j0 + 1) > 400) continue
    try {
      for (let j = j0; j <= j1; j++) {
        for (let i = i0; i <= i1; i++) {
          ctx.save()
          ctx.translate(x0 + i * tw, y0 + j * th)
          if (source) ctx.drawImage(source, 0, 0, tw, th)
          else fillGradient(ctx, image as Gradient, tw, th)
          ctx.restore()
        }
      }
    } catch {
      // A colour this browser's canvas cannot parse: the layer is left out
      // (the gradient is built before anything else is saved, so one restore is owed).
      ctx.restore()
    }
  }
}

// ââ Text and backdrop blur âââââââââââââââââââââââââââââââââââââââââââââââââââ

/** Draws one text node line by line, where the page laid it out and in its own font. */
function drawText(
  ctx: CanvasRenderingContext2D,
  node: Text,
  style: CSSStyleDeclaration,
  originX: number,
  originY: number,
  lang: string | undefined,
  isVisible: (rect: DOMRect) => boolean,
  range: Range
) {
  const raw = node.textContent ?? ""
  let text = raw.replace(/\s+/g, " ").trim()
  if (!text) return
  range.selectNodeContents(node)
  const lines = [...range.getClientRects()].filter((rect) => rect.width > 0.5)
  // No line of it shows: its font is not set up and nothing is measured.
  if (!lines.some(isVisible)) return
  // The page shows the transformed text. Upper and lower case follow the page's
  // language (Turkish i â Ä°); browsers capitalise without it.
  const transform = style.textTransform
  if (transform === "uppercase") text = text.toLocaleUpperCase(lang)
  else if (transform === "lowercase") text = text.toLocaleLowerCase(lang)
  else if (transform === "capitalize")
    text = text.replace(
      /(^|\s)(\S)/g,
      (_, gap: string, letter: string) => gap + letter.toUpperCase()
    )
  const rtl = style.direction === "rtl"
  ctx.font = `${style.fontStyle} ${style.fontWeight} ${style.fontSize} ${style.fontFamily}`
  if ("letterSpacing" in ctx)
    ctx.letterSpacing =
      style.letterSpacing === "normal" ? "0px" : style.letterSpacing
  ctx.direction = rtl ? "rtl" : "ltr"
  ctx.textAlign = "left"
  ctx.fillStyle = style.color
  ctx.textBaseline = "alphabetic"
  const metrics = ctx.measureText("HgÄ°Å")
  const ascent = metrics.fontBoundingBoxAscent
  const descent = metrics.fontBoundingBoxDescent
  const space = ctx.measureText(" ").width
  // Fill each line with as many words as fit (a single line takes them all).
  const words = text.split(" ")
  let next = 0
  lines.forEach((rect, i) => {
    let line = ""
    if (i === lines.length - 1) line = words.slice(next).join(" ")
    else {
      while (next < words.length) {
        const candidate = line ? `${line} ${words[next]}` : words[next]
        if (line && ctx.measureText(candidate).width > rect.width + 1) break
        line = candidate
        next++
      }
    }
    if (!line || !isVisible(rect)) return
    // A leading space takes room only after an inline neighbour (not at the start of a
    // block): then the line box is wider than its words, and the text starts further in.
    const lead =
      i === 0 &&
      !rtl &&
      /^\s/.test(raw) &&
      rect.width - ctx.measureText(line).width > space * 0.5
        ? space
        : 0
    const baseline =
      rect.top - originY + (rect.height - (ascent + descent)) / 2 + ascent
    ctx.fillText(line, rect.left - originX + lead, baseline)
  })
}

let scratch: HTMLCanvasElement | undefined

/**
 * Blurs a box of the canvas in place (the counterpart of `backdrop-filter: blur()`).
 * Like CSS, only what is inside the box is blurred and its edge pixels repeat outwards,
 * so content next to a frosted bar does not bleed into it.
 */
function blurBackdrop(
  ctx: CanvasRenderingContext2D,
  box: Box,
  radius: number,
  blurPx: number
) {
  const matrix = ctx.getTransform()
  const scale = matrix.a
  // (A context may be scaled a hair differently each way: the engine fits a small picture to its canvas.)
  const scaleY = matrix.d
  const left = Math.max(0, Math.floor(box.x * scale + matrix.e))
  const top = Math.max(0, Math.floor(box.y * scaleY + matrix.f))
  const w =
    Math.min(ctx.canvas.width, Math.ceil((box.x + box.w) * scale + matrix.e)) -
    left
  const h =
    Math.min(
      ctx.canvas.height,
      Math.ceil((box.y + box.h) * scaleY + matrix.f)
    ) - top
  if (w < 1 || h < 1) return
  const pad = Math.ceil(blurPx * scale * 3)
  scratch ??= document.createElement("canvas")
  scratch.width = w + 2 * pad
  scratch.height = h + 2 * pad
  const copy = scratch.getContext("2d")
  if (!copy) return
  copy.imageSmoothingEnabled = false
  copy.drawImage(ctx.canvas, left, top, w, h, pad, pad, w, h)
  copy.drawImage(scratch, pad, pad, 1, h, 0, pad, pad, h)
  copy.drawImage(scratch, pad + w - 1, pad, 1, h, pad + w, pad, pad, h)
  copy.drawImage(scratch, 0, pad, w + 2 * pad, 1, 0, 0, w + 2 * pad, pad)
  copy.drawImage(
    scratch,
    0,
    pad + h - 1,
    w + 2 * pad,
    1,
    0,
    pad + h,
    w + 2 * pad,
    pad
  )
  ctx.save()
  ctx.beginPath()
  ctx.roundRect(box.x, box.y, box.w, box.h, radius)
  ctx.clip()
  ctx.setTransform(1, 0, 0, 1, 0, 0)
  ctx.globalAlpha = 1
  ctx.clearRect(left, top, w, h)
  ctx.filter = `blur(${blurPx * scale}px)`
  ctx.drawImage(scratch, left - pad, top - pad)
  ctx.restore()
}

// ââ The walk âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

/**
 * Where a child paints among its siblings (CSS 2.1 appendix E, per parent):
 * 0 negative z-index, 1 content in the flow, 2 positioned and stacking boxes, 3 positive z-index.
 */
function layerOf(
  style: CSSStyleDeclaration,
  inFlexOrGrid: boolean
): [layer: number, z: number] {
  const positioned = style.position !== "static"
  const z =
    (positioned || inFlexOrGrid) && style.zIndex !== "auto"
      ? parseInt(style.zIndex, 10) || 0
      : 0
  if (z) return [z < 0 ? 0 : 3, z]
  const stacks =
    positioned ||
    style.opacity !== "1" ||
    style.transform !== "none" ||
    style.filter !== "none" ||
    style.isolation === "isolate" ||
    (style.backdropFilter || "none") !== "none"
  return [stacks ? 2 : 1, 0]
}

export type DomSnapshotOptions = {
  /**
   * The viewport point that lands on the context's origin, in CSS px.
   * Pass a `getBoundingClientRect()` result; only `left` and `top` are read.
   */
  origin: { left: number; top: number }
  /** Visit only elements whose box intersects this viewport rectangle. */
  region?: { left: number; top: number; right: number; bottom: number }
  /** Return true to leave an element and everything inside it out. */
  skip?: (element: Element) => boolean
  /** Called when an image or an SVG that was not ready has loaded: draw again. */
  onStale?: () => void
  /** Any string that changes when icon colours may have changed, such as the theme name. */
  cacheKey?: string
  /**
   * Filled in by the walk, for a caller that wants to know whether its picture survives a scroll:
   * `pinned` gets every fixed or sticky element met, `touched` says one of them reaches the region,
   * and `loose` that something painted may move by itself (an animation, an inline transform, a fixed background).
   */
  found?: { pinned: Element[]; touched: boolean; loose: boolean }
}

/**
 * Paints `root` and everything inside it into `ctx`. The context must already be
 * scaled so that one unit is one CSS px. Boxes that clip their overflow clip their
 * children; fixed and sticky elements are painted last, on top.
 */
/** A computed `clip-path` of the `inset()` or `path()` kind as a canvas path; anything else is not clipped. */
function clipShape(value: string, box: Box): Path2D | null {
  if (!value || value === "none") return null
  const path = /^path\((?:[a-z-]+\s*,\s*)?["'](.*)["']\)$/s.exec(value)
  if (path) {
    const shape = new Path2D()
    shape.addPath(new Path2D(path[1]), new DOMMatrix().translate(box.x, box.y))
    return shape
  }
  const inset = /^inset\((.*)\)$/s.exec(value)
  if (!inset) return null
  const [sides, round = ""] = inset[1].split(/\s+round\s+/)
  const length = (token: string, of: number) =>
    token.endsWith("%")
      ? (parseFloat(token) / 100) * of
      : parseFloat(token) || 0
  const t = sides.trim().split(/\s+/)
  const top = length(t[0], box.h)
  const right = length(t[1] ?? t[0], box.w)
  const bottom = length(t[2] ?? t[0], box.h)
  const left = length(t[3] ?? t[1] ?? t[0], box.w)
  const w = Math.max(0, box.w - left - right)
  const h = Math.max(0, box.h - top - bottom)
  const shape = new Path2D()
  shape.roundRect(
    box.x + left,
    box.y + top,
    w,
    h,
    Math.min(
      round ? length(round.trim().split(/\s+/)[0], Math.min(w, h)) : 0,
      w / 2,
      h / 2
    )
  )
  return shape
}

/** Screen-reader-only text (a 1 px square) and empty boxes: never painted. */
const isEmpty = (rect: DOMRect) =>
  rect.width <= 0 || rect.height <= 0 || (rect.width <= 1 && rect.height <= 1)

let locale: { of: string; is: string | undefined } | undefined
/** The page's language as a locale, worked out once for each value of `lang`. */
function localeOf(lang: string) {
  if (locale?.of === lang) return locale.is
  let is: string | undefined
  try {
    is = Intl.getCanonicalLocales(lang)[0]
  } catch {
    // Not a language tag: the default locale's rules apply.
  }
  locale = { of: lang, is }
  return is
}

export function drawDom(
  ctx: CanvasRenderingContext2D,
  root: Element,
  options: DomSnapshotOptions
) {
  const {
    origin,
    region,
    skip,
    onStale,
    cacheKey = document.documentElement.className,
    found,
  } = options
  const originX = origin.left
  const originY = origin.top
  const deferred: { element: Element; opacity: number }[] = []
  const intersects = (rect: DOMRect) =>
    !region ||
    (rect.right > region.left &&
      rect.left < region.right &&
      rect.bottom > region.top &&
      rect.top < region.bottom)
  const lang = localeOf(document.documentElement.lang)
  const range = document.createRange()

  const walk = (
    element: Element,
    parentOpacity: number,
    isDeferred = false,
    style = getComputedStyle(element),
    measured?: DOMRect
  ) => {
    if (skip?.(element)) return
    if (style.display === "none" || style.visibility === "hidden") return
    const opacity = parentOpacity * Number(style.opacity)
    if (opacity < 0.01) return
    if (
      !isDeferred &&
      element !== root &&
      (style.position === "fixed" || style.position === "sticky")
    ) {
      deferred.push({ element, opacity: parentOpacity })
      found?.pinned.push(element)
      return
    }
    const drawChildren = () => {
      const inFlexOrGrid = /flex|grid/.test(style.display)
      const children: {
        node: ChildNode
        childStyle: CSSStyleDeclaration | null
        layer: number
        z: number
        rect?: DOMRect
      }[] = []
      for (const node of element.childNodes) {
        if (!(node instanceof Element)) {
          children.push({ node, childStyle: null, layer: 1, z: 0 })
          continue
        }
        const childStyle = getComputedStyle(node)
        // Most siblings on the way down to the region lie outside it, and nothing of such a box is
        // painted (see `walk`): it is left out here, before its place among its siblings is worked
        // out, which takes most of what is read of an element. Kept whatever its box: an element
        // pinned to the viewport (it is met again at the end, and reported in `found`) and one
        // without a box of its own (`display: contents`).
        let rect: DOMRect | undefined
        if (
          childStyle.position !== "fixed" &&
          childStyle.position !== "sticky" &&
          childStyle.display !== "contents"
        ) {
          rect = node.getBoundingClientRect()
          if (isEmpty(rect) || !intersects(rect)) continue
        }
        const [layer, z] = layerOf(childStyle, inFlexOrGrid)
        children.push({ node, childStyle, layer, z, rect })
      }
      // The sort is stable: within a layer, document order.
      children.sort((a, b) => a.layer - b.layer || a.z - b.z)
      for (const { node, childStyle, rect } of children) {
        if (childStyle) walk(node as Element, opacity, false, childStyle, rect)
        else if (node.nodeType === Node.TEXT_NODE) {
          ctx.globalAlpha = opacity
          drawText(
            ctx,
            node as Text,
            style,
            originX,
            originY,
            lang,
            intersects,
            range
          )
        }
      }
    }
    if (style.display === "contents") {
      drawChildren()
      return
    }
    // (Nothing on the page moves during a walk: a box measured among its siblings is still right.)
    const rect = measured ?? element.getBoundingClientRect()
    // Screen-reader-only text (a 1 px square) and empty boxes are not painted, a hairline is;
    // nothing outside the region is visited.
    if (isEmpty(rect) || !intersects(rect)) return
    if (found) {
      if (isDeferred) found.touched = true
      else if (!found.loose) {
        // A transform from a stylesheet stays put (a centred box); one written inline is a script's, and may follow the scroll.
        const inline = (element as HTMLElement).style as
          CSSStyleDeclaration | undefined
        found.loose =
          style.animationName !== "none" ||
          (style.backgroundImage !== "none" &&
            style.backgroundAttachment.includes("fixed")) ||
          (!!inline &&
            !!(
              inline.transform ||
              inline.translate ||
              inline.rotate ||
              inline.scale
            ))
      }
    }
    const box: Box = {
      x: rect.left - originX,
      y: rect.top - originY,
      w: rect.width,
      h: rect.height,
    }
    // A `clip-path` (inset or path) cuts the box and everything inside it, as on screen.
    const shape = clipShape(style.clipPath, box)
    if (shape) {
      ctx.save()
      ctx.clip(shape)
    }
    try {
      paintBox(element, style, rect, box, opacity, drawChildren)
    } finally {
      if (shape) ctx.restore()
    }
  }
  const paintBox = (
    element: Element,
    style: CSSStyleDeclaration,
    rect: DOMRect,
    box: Box,
    opacity: number,
    drawChildren: () => void
  ) => {
    const radius = Math.min(
      parseFloat(style.borderTopLeftRadius) || 0,
      rect.width / 2,
      rect.height / 2
    )
    // Frosted veil (backdrop-filter: blur): blur what is already painted beneath it first,
    // otherwise text behind a translucent veil shows up sharp in the glass.
    const backdropBlur = /blur\(([\d.]+)px\)/.exec(style.backdropFilter)
    if (backdropBlur) blurBackdrop(ctx, box, radius, Number(backdropBlur[1]))
    ctx.globalAlpha = opacity
    // `background-clip: text` paints the background inside the letters only: no box.
    const hasBox = style.backgroundClip !== "text"
    if (hasBox && isVisibleColor(style.backgroundColor)) {
      ctx.beginPath()
      ctx.roundRect(box.x, box.y, box.w, box.h, radius)
      ctx.fillStyle = style.backgroundColor
      ctx.fill()
    }
    if (hasBox && style.backgroundImage !== "none") {
      // The part of the box inside the region: only the tiles that reach it are painted.
      const bounds = { ...box }
      if (region) {
        bounds.x = Math.max(box.x, region.left - originX)
        bounds.y = Math.max(box.y, region.top - originY)
        bounds.w = Math.min(box.x + box.w, region.right - originX) - bounds.x
        bounds.h = Math.min(box.y + box.h, region.bottom - originY) - bounds.y
      }
      // A fixed background is laid out in the viewport, whatever the element's box.
      const area: Box = style.backgroundAttachment.includes("fixed")
        ? { x: -originX, y: -originY, w: innerWidth, h: innerHeight }
        : box
      ctx.save()
      ctx.beginPath()
      ctx.roundRect(box.x, box.y, box.w, box.h, radius)
      ctx.clip()
      paintBackgrounds(ctx, style, area, bounds, onStale)
      ctx.restore()
    }
    const borderWidth = parseFloat(style.borderTopWidth) || 0
    if (
      borderWidth > 0 &&
      style.borderTopStyle !== "none" &&
      isVisibleColor(style.borderTopColor)
    ) {
      ctx.beginPath()
      ctx.roundRect(
        box.x + borderWidth / 2,
        box.y + borderWidth / 2,
        box.w - borderWidth,
        box.h - borderWidth,
        Math.max(0, radius - borderWidth / 2)
      )
      ctx.lineWidth = borderWidth
      ctx.strokeStyle = style.borderTopColor
      ctx.setLineDash(style.borderTopStyle === "dashed" ? [4, 3] : [])
      ctx.stroke()
      ctx.setLineDash([])
    }
    if (element instanceof SVGSVGElement) {
      drawSvg(ctx, element, style.color, box, onStale, cacheKey)
      return
    }
    if (element instanceof HTMLCanvasElement) {
      if (element.width && element.height && isClean(element))
        ctx.drawImage(element, box.x, box.y, box.w, box.h)
      return
    }
    if (element instanceof HTMLImageElement) {
      const src = element.currentSrc || element.src
      if (!src) return
      // The element itself when the canvas stays readable, otherwise our own CORS copy.
      const image =
        element.complete && element.naturalWidth && isClean(element, src)
          ? element
          : imageCopy(src)
      if (isLoaded(image, onStale) && isClean(image, src))
        drawFitted(
          ctx,
          image,
          image.naturalWidth,
          image.naturalHeight,
          box,
          radius,
          style
        )
      return
    }
    if (element instanceof HTMLVideoElement) {
      // The current frame; `live` glass follows the playback.
      if (
        element.readyState >= 2 &&
        element.videoWidth &&
        isClean(element, element.currentSrc)
      )
        drawFitted(
          ctx,
          element,
          element.videoWidth,
          element.videoHeight,
          box,
          radius,
          style
        )
      return
    }
    const clips =
      element !== root &&
      style.overflow !== "visible" &&
      element !== document.body &&
      element !== document.documentElement
    if (clips) {
      ctx.save()
      ctx.beginPath()
      ctx.roundRect(box.x, box.y, box.w, box.h, radius)
      ctx.clip()
    }
    drawChildren()
    if (clips) ctx.restore()
  }
  walk(root, 1)
  for (let i = 0; i < deferred.length; i++)
    walk(deferred[i].element, deferred[i].opacity, true)
  ctx.globalAlpha = 1
}

/**
 * Paints what surrounds a box of the viewport, `reach` px past it on every side, with the box's
 * top-left on the context's origin: what a glass rim mirrors (`GlassLens.reflection`).
 */
export function drawAround(
  ctx: CanvasRenderingContext2D,
  root: Element,
  box: { left: number; top: number; width: number; height: number },
  reach: number,
  options: Pick<DomSnapshotOptions, "skip" | "onStale">
) {
  drawDom(ctx, root, {
    ...options,
    origin: box,
    region: {
      left: box.left - reach,
      top: box.top - reach,
      right: box.left + box.width + reach,
      bottom: box.top + box.height + reach,
    },
  })
}
